const ECONOMICS_QUESTIONS = [
    { id: 1, text: "На любой стадии рассмотрения дела о банкротстве в целях прекращения производства по делу может быть применена процедура:", options: ["Мирового соглашения;", "Наблюдения;", "Внешнего управления;", "Конкурсного производства;"], correct: 0, topic: "Банкротство" },
    { id: 2, text: "Государственная форма собственности в России не характерна для:", options: ["Легкой промышленности;", "Фундаментальной науки;", "Экологической защиты;", "Центрального Банка России;", "Оборонной промышленности;"], correct: 0, topic: "Собственность" },
    { id: 3, text: "Меры по восстановлению платежеспособности, принимаемые собственником имущества должника – унитарного предприятия, учредителями, кредиторами в рамках мер по предупреждению банкротства должника, называются:", options: ["Досудебной санацией;", "Наблюдением;", "Финансовым оздоровлением;", "Внешним управлением;"], correct: 0, topic: "Банкротство" },
    { id: 4, text: "К некоммерческим организациям не относят:", options: ["Хозяйственное товарищество «Надежда»;", "Фонд культуры;", "Гимназию №1 г. Стерлитамака;", "Политическую партию «Народное достояние»;"], correct: 0, topic: "Организационно-правовые формы" },
    { id: 5, text: "Примером частной ________ собственности выступает общество с ограниченной ответственностью.", options: ["Групповой;", "Корпоративный;", "Коллективной;", "Личной."], correct: 0, topic: "Организационно-правовые формы" },
    { id: 6, text: "Ограниченная ответственность учредителей возможна в: (выберите не менее 2 правильных ответов)", options: ["Обществе с ограниченной ответственностью;", "Акционерном обществе;", "Полном товариществе;", "Коммандитном товариществе;"], correct: [0, 1], topic: "Организационно-правовые формы" },
    { id: 7, text: "Ограничения по минимальному составу учредителей имеют: (выберите не менее 2 правильных ответов)", options: ["Товарищество на вере;", "Производственный кооператив;", "Общество с ограниченной ответственностью;", "Открытое акционерное общество;"], correct: [0, 1], topic: "Организационно-правовые формы" },
    { id: 8, text: "Индивидуальный предприниматель, признанный банкротом, не может быть снова зарегистрирован в качестве индивидуального предпринимателя в течение _____ с момента признания его банкротства.", options: ["Года;", "5 лет;", "10 лет;", "6 месяцев;"], correct: 0, topic: "Банкротство" },
    { id: 9, text: "Первоочередными мерами при реформировании товарищества являются: (выберите не менее 2 правильных ответов)", options: ["Модернизация оборудования, контроль за качеством продукции;", "Снижение текучести кадров;", "Перераспределение собственности (пакетов ценных бумаг);", "Чистка портфеля ценных бумаг."], correct: [0, 1], topic: "Реформирование предприятий" },
    { id: 10, text: "Учредительный договор как единственный необходимый и достаточный учредительный документ характерен для:", options: ["Товарищества на вере;", "Общества с ограниченной ответственностью;", "Закрытого акционерного общества;", "Унитарного предприятия;"], correct: 0, topic: "Организационно-правовые формы" },
    { id: 11, text: "Предметы личного потребления выступают объектами _____ или личной форм собственности.", options: ["Общей совместной;", "Муниципальной;"], correct: 0, topic: "Собственность" },
    { id: 12, text: "В Российской Федерации детские сады преимущественно являются объектом собственности.", options: ["Муниципальной;", "Федеральной;", "Региональной;", "Общенародной;", "Частной;"], correct: 0, topic: "Собственность" },
    { id: 13, text: "Хозяйственное общество, учредителем которого выступает субъект Российской Федерации, образуется в форме:", options: ["Открытого акционерного общества;", "Общества с ограниченной ответственностью;", "Закрытого акционерного общества;", "Общества с дополнительной ответственностью;"], correct: 0, topic: "Организационно-правовые формы" },
    { id: 14, text: "Совместно-долевая собственность не может выступать в форме имущества:", options: ["Российской Федерации;", "Семьи на основе брачного контракта;", "Товарищества на вере;", "Закрытого акционерного общества;"], correct: 0, topic: "Собственность" },
    { id: 15, text: "В современной экономической системе _____ относится к объекту муниципальной собственности.", options: ["Троллейбусный транспорт;", "Скутер;", "Кафе;", "Косметика;", "Кинотеатры"], correct: 0, topic: "Собственность" },
    { id: 16, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Рентабельность продаж (%) составит:", options: ["13,3", "15,4;", "37,4", "59,9;", "86,7;"], correct: 0, topic: "Рентабельность" },
    { id: 17, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р., среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Рентабельность производственных фондов (%) составит:", options: ["59,9;", "15,4;", "13,3;", "37,4", "86,7;"], correct: 0, topic: "Рентабельность" },
    { id: 18, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р., среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Рентабельность продукции (%) составит:", options: ["15,4;", "13,3;", "37,4", "59,9;", "86,7;"], correct: 0, topic: "Рентабельность" },
    { id: 19, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Чистая прибыль (тыс.р.) составит:", options: ["5480.", "5130;", "3150;", "6850", "36130;"], correct: 0, topic: "Прибыль" },
    { id: 20, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р., среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Прибыль от реализации продукции (тыс.р.) составит:", options: ["5000.", "6500;", "3150;", "6850", "37500;"], correct: 0, topic: "Прибыль" },
    { id: 21, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р., среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Прибыль балансовая (тыс.р.) составит:", options: ["6850", "6500;", "3150;", "37500;", "5000"], correct: 0, topic: "Прибыль" },
    { id: 22, text: "Предприятие выпускает в месяц 300 ед. продукции и реализует ее по цене 100 рублей. Чтобы месячная прибыль составила 12 тыс. рублей, рентабельность продукции должна быть  %:", options: ["66.7;", "120;", "40;", "60;"], correct: 0, topic: "Рентабельность" },
    { id: 23, text: "Деятельность некоторого предприятия может быть охарактеризована следующими данными: за отчетный период было произведено и реализовано продукции на сумму 720 тыс. руб., среднегодовая стоимость основных производственных фондов составила 110 тыс. руб., средний остаток оборотных средств – 88 тыс. руб., амортизация – 20 тыс. руб., численность рабочих – 20 человек, прибыль от реализации продукции – 68 тыс. руб. Показатель рентабельности производства составит:", options: ["0,34;", "6,55;", "0,15;", "9,4"], correct: 0, topic: "Рентабельность" },
    { id: 24, text: "Производство капусты является целесообразным, если рентабельность продукции равна 25%. Цена тонны капусты ожидается на уровне 22,5 тыс. рублей, тогда максимально допустимая себестоимость тонны капусты составит рублей.", options: ["18000;", "16875;", "22500;", "5625;"], correct: 0, topic: "Себестоимость" },
    { id: 25, text: "Деятельность некоторого предприятия может быть охарактеризована следующими данными: постоянные затраты – 40 тыс. руб., цена реализации единицы продукции – 80 руб., переменные затраты на единицу продукции – 55 руб., объем реализации – 800 ед. продукции. Согласно этим данным безубыточный объем производства составит ед. продукции.", options: ["1600;", "500;", "727;"], correct: 0, topic: "Точка безубыточности" },
    { id: 26, text: "Показатель рентабельности продаж определяется следующим образом:", options: ["Отношение прибыли от реализации продукции к выручке от ее реализации, выраженное в процентах;", "Отношение выручки от реализации продукции к балансовой прибыли предприятия, выраженное в процентах;", "Отношение прибыли от реализации продукции к балансовой прибыли предприятия, выраженное в процентах;", "Отношение прибыли от реализации продукции к себестоимости реализованной продукции, выраженное в процентах;", "Отношение себестоимости реализованной продукции к прибыли от ее реализации, выраженное в процентах;"], correct: 0, topic: "Рентабельность" },
    { id: 27, text: "Показатель рентабельности продукции определяется следующим образом:", options: ["Отношение прибыли от реализации продукции к себестоимости реализованной продукции, выраженное в процентах;", "Отношение выручки от реализации продукции к балансовой прибыли предприятия, выраженное в процентах;", "Отношение прибыли от реализации продукции к балансовой прибыли предприятия, выраженное в процентах;", "Отношение прибыли от реализации продукции к выручке от ее реализации, выраженное в процентах;", "Отношение себестоимости реализованной продукции к прибыли от ее реализации, выраженное в процентах;"], correct: 0, topic: "Рентабельность" },
    { id: 28, text: "Показатель рентабельности производственных фондов рассчитывается как:", options: ["Отношение балансовой прибыли предприятия к сумме среднегодовой стоимости основных производственных фондов и нормируемых оборотных средств, выраженное в процентах;", "Отношение суммы среднегодовой стоимости основных производственных фондов и нормируемых оборотных средств к балансовой прибыли предприятия, выраженное в процентах;", "Отношение прибыли от реализации продукции к сумме среднегодовой стоимости основных производственных фондов и нормируемых оборотных средств, выраженное в процентах;", "Отношение выручки от реализации продукции к среднегодовой стоимости основных производственных фондов, выраженное в процентах;", "Отношение среднегодовой стоимости основных производственных фондов к выручке от реализации продукции, выраженное в процентах;"], correct: 0, topic: "Рентабельность" },
    { id: 29, text: "Прибыль от реализации продукции рассчитывается как:", options: ["Разность между выручкой от реализации продукции и себестоимостью реализованной продукции;", "Разность между себестоимостью реализованной продукции и выручкой от реализации продукции;", "Сумма себестоимости реализованной продукции и прибыли от прочей реализации;", "Разность между внереализационными доходами и расходами;"], correct: 0, topic: "Прибыль" },
    { id: 30, text: "Балансовая прибыль рассчитывается как:", options: ["Сумма прибыли от реализации продукции и от прочей реализации с учетом внереализационных доходов и расходов;", "Разность между выручкой от реализации продукции и себестоимостью реализованной продукции;", "Разность между себестоимостью реализованной продукции и выручкой от реализации продукции;", "Сумма себестоимости реализованной продукции и прибыли от прочей реализации;", "Сумма прибыли от реализации продукции и от прочей реализации;", "Сумма прибыли от реализации продукции и налога на прибыль;"], correct: 0, topic: "Прибыль" },
    { id: 31, text: "Какие показатели не планируют при организации деятельности транспортного хозяйства:", options: ["Грузоподъемность транспортного средства.", "Грузопоток;", "Грузооборот;", "Схема маршрутных перевозок;", "Необходимое число рабочих;"], correct: 0, topic: "Вспомогательное хозяйство" },
    { id: 32, text: "Какие функции не выполняет служба КИПиА:", options: ["Усовершенствование технологических процессов производства продукции;", "Текущий надзор за работой контрольно-измерительных приборов и их регулирование;", "Ремонт контрольно-измерительных приборов, их паспортизация и регистрация их работы;", "Усовершенствование действующих приборов и схем автоматизации технологических процессов;", "Ведомственный надзор за измерительными приборами;"], correct: 0, topic: "Вспомогательное хозяйство" },
    { id: 33, text: "По какому типу не может быть организована структура службы маркетинга:", options: ["Консалтинговый;", "Функциональный;", "Товарный;", "Рыночный;", "Региональный;", "Смешанный;"], correct: 0, topic: "Маркетинг" },
    { id: 34, text: "Планируемая численность рабочих транспортной службы определяется (выберите не менее 2 правильных ответов):", options: ["По трудоемкости программы;", "По штатным точкам.", "На основе нормы обслуживания;", "На основе выработки продукции;", "По графику перевозок;"], correct: [0, 1], topic: "Планирование численности" },
    { id: 35, text: "Планируемая численность рабочих службы КИПиА определяется (выберите не менее 2 правильных ответов):", options: ["По расстановочному штату;", "По трудоемкости программы;", "На основе выработки продукции;", "По штатным точкам.", "По графику планово-предупредительных работ;"], correct: [0, 1], topic: "Планирование численности" },
    { id: 36, text: "Управление персоналом не включает следующее направление:", options: ["Техногенное", "Научно-техническое", "Производственное", "Экономическое", "Социальное"], correct: 0, topic: "Управление персоналом" },
    { id: 37, text: "Учредительный договор как единственный необходимый и достаточный учредительный документ характерен для:", options: ["Товарищества на вере;", "Общества с ограниченной ответственностью;", "Закрытого акционерного общества;", "Унитарного предприятия;"], correct: 0, topic: "Организационно-правовые формы" },
    { id: 38, text: "Ограничения по минимальному составу учредителей имеют: (выберите не менее 2 правильных ответов)", options: ["Товарищество на вере;", "Производственный кооператив;", "Общество с ограниченной ответственностью;", "Открытое акционерное общество;"], correct: [0, 1], topic: "Организационно-правовые формы" },
    { id: 39, text: "Ограниченное количество учредителей (не более 50) – это условие для (выберите не менее 2 правильных ответов)", options: ["Общества с ограниченной ответственностью;", "Общества с ограниченной ответственностью;", "Кооператива;", "Товарищества на вере;"], correct: [0, 1], topic: "Организационно-правовые формы" },
    { id: 40, text: "При банкротстве должника-гражданина (за исключением фермерских хозяйств) в деле о банкротстве может быть применена процедура:", options: ["Конкурсного производства;", "Наблюдения;", "Внешнего управления;", "Финансового оздоровления;"], correct: 0, topic: "Банкротство" },
    { id: 41, text: "Ограниченная ответственность учредителей возможна в: (выберите не менее 2 правильных ответов)", options: ["Общество с ограниченной ответственностью;", "Акционерном обществе;", "Полном товариществе;", "Коммандитном товариществе;"], correct: [0, 1], topic: "Организационно-правовые формы" },
    { id: 42, text: "Первоочередными мерами при реформировании товарищества являются: (выберите не менее 2 правильных ответов)", options: ["Модернизация оборудования, контроль за качеством продукции;", "Снижение текучести кадров;", "Перераспределение собственности(пакетов ценных бумаг);", "Чистка портфеля ценных бумаг."], correct: [0, 1], topic: "Реформирование предприятий" },
    { id: 43, text: "Индивидуальный предприниматель, признанный банкротом, не может быть снова зарегистрирован в качестве индивидуального предпринимателя в течение______ с момента признания его банкротства.", options: ["Года;", "5 лет;", "10 лет;", "6 месяцев."], correct: 0, topic: "Банкротство" },
    { id: 44, text: "Хозяйственное общество, учредителем которого выступает субъект Российской Федерации, образуется в форме:", options: ["Открытого акционерного общества;", "Общества с ограниченной ответственностью;", "Закрытого акционерного общества;", "Общества с дополнительной ответственностью."], correct: 0, topic: "Организационно-правовые формы" },
    { id: 45, text: "В Российской Федерации детские сады преимущественно являются объектом _________ собственности.", options: ["Муниципальной;", "Федеральной;", "Региональной;", "Общенародной;", "Частной."], correct: 0, topic: "Формы собственности" },
    { id: 46, text: "Предметы личного потребления выступают объектами________ или личной форм собственности.", options: ["Общей совместной;", "Муниципальной;", "Семейной долевой;", "Общественной."], correct: 0, topic: "Формы собственности" },
    { id: 47, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации-1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р., среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р.\nРентабельность продукции(%) составит:", options: ["15,4;", "13,3;", "37,4", "59,9;", "86,7."], correct: 0, topic: "Показатели эффективности" },
    { id: 48, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р., среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Прибыль балансовая (тыс.р.) составит:", options: ["6850", "6500;", "3150;", "37500;", "5000"], correct: 0, topic: "Прибыль" },
    { id: 49, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р., среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Рентабельность производственных фондов (%) составит:", options: ["59,9;", "15,4;", "13,3;", "37,4", "86,7;"], correct: 0, topic: "Рентабельность" },
    { id: 50, text: "Деятельность некоторого предприятия может быть охарактеризована следующими данными: за отчетный период было произведено и реализовано продукции на сумму 720 тыс. руб., среднегодовая стоимость основных производственных фондов составила 110 тыс. руб., средний остаток оборотных средств – 88 тыс. руб., амортизация – 20 тыс. руб., численность рабочих – 20 человек, прибыль от реализации продукции – 68 тыс. руб. Показатель рентабельности производства составит:", options: ["0,34;", "6,55;", "0,15;", "9,4"], correct: 0, topic: "Рентабельность" },
    { id: 51, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Чистая прибыль (тыс.р.) составит:", options: ["5480.", "5130:", "3150:", "6850", "36130:"], correct: 0, topic: "Прибыль" },
    { id: 52, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Прибыль от реализации продукции (тыс.р.) составит:", options: ["5000.", "6500:", "3150:", "6850", "37500:"], correct: 0, topic: "Прибыль" },
    { id: 53, text: "Деятельность некоторого предприятия может быть охарактеризована следующими данными: постоянные затраты – 40 тыс. руб., цена реализации единицы продукции – 80 руб., переменные затраты на единицу продукции – 55 руб., объем реализации – 800 ед. продукции. Согласно этим данным безубыточный объем производства составит ед. продукции.", options: ["1600:", "500:", "727:", "1760."], correct: 0, topic: "Точка безубыточности" },
    { id: 54, text: "Показатель рентабельности имущества рассчитывается как:", options: ["Отношение балансовой прибыли предприятия к стоимости имущества, выраженное в процентах;", "Отношение стоимости имущества к балансовой прибыли предприятия, выраженное в процентах;", "Отношение прибыли от реализации продукции к стоимости имущества, выраженное в процентах;", "Отношение выручки от реализации продукции к стоимости имущества, выраженное в процентах;", "Отношение стоимости имущества к выручке от реализации продукции, выраженное в процентах;"], correct: 0, topic: "Рентабельность" },
    { id: 55, text: "Показатель рентабельности продукции определяется следующим образом:", options: ["Отношение прибыли от реализации продукции к себестоимости реализованной продукции, выраженное в процентах;", "Отношение выручки от реализации продукции к балансовой прибыли предприятия, выраженное в процентах;", "Отношение прибыли от реализации продукции к балансовой прибыли предприятия, выраженное в процентах;", "Отношение прибыли от реализации продукции к выручке от ее реализации, выраженное в процентах;", "Отношение себестоимости реализованной продукции к прибыли от ее реализации, выраженное в процентах;"], correct: 0, topic: "Рентабельность" },
    { id: 56, text: "Прибыль от реализации продукции рассчитывается как:", options: ["Разность между выручкой от реализации продукции и себестоимостью реализованной продукции;", "Разность между себестоимостью реализованной продукции и выручкой от реализации продукции;", "Сумма себестоимости реализованной продукции и прибыли от прочей реализации;", "Разность между внереализационными доходами и расходами;", "Сумма себестоимости реализованной продукции и налога на прибыль;"], correct: 0, topic: "Прибыль" },
    { id: 57, text: "Что не относится к основным задачам энергохозяйства:", options: ["Рациональное использование сырья и материалов;", "Бесперебойное обеспечение предприятия всеми видами энергии;", "Рациональное использование энергетического оборудования»", "Ремонт и обслуживание энергетического оборудования;", "Экономное расходование всех видов энергии;"], correct: 0, topic: "Вспомогательное хозяйство" },
    { id: 58, text: "Планируемая численность ремонтных рабочих определяется:", options: ["По трудоемкости программы;", "На основе нормы обслуживания;", "По штатным точкам;", "По расстановочному штату.", "По графику планово-предупредительных работ;"], correct: 0, topic: "Планирование численности" },
    { id: 59, text: "Планируемая численность рабочих транспортной службы определяется (выберите не менее 2 правильных ответов):", options: ["По трудоемкости программы;", "По штатным точкам.", "На основе нормы обслуживания;", "На основе выработки продукции;", "По графику перевозок;"], correct: [0, 1], topic: "Планирование численности" },
    { id: 60, text: "По какому типу не может быть организована структура службы маркетинга:", options: ["Консалтинговый;", "Функциональный;", "Товарный;", "Рыночный;", "Региональный;", "Смешанный;"], correct: 0, topic: "Маркетинг" },
    { id: 61, text: "Планируемая численность рабочих энергохозяйства определяется:", options: ["По трудоемкости программы;", "На основе нормы обслуживания;", "По штатным точкам;", "По расстановочному штату.", "По графику планово-предупредительных работ;"], correct: 0, topic: "Планирование численности" },
    { id: 62, text: "Какие функции не выполняет служба КИПиА:", options: ["Усовершенствование технологических процессов производства продукции;", "Текущий надзор за работой контрольно-измерительных приборов и их регулирование;", "Ремонт контрольно-измерительных приборов, их паспортизация и регистрация их работы;", "Усовершенствование действующих приборов и схем автоматизации технологических процессов;", "Ведомственный надзор за измерительными приборами;"], correct: 0, topic: "Вспомогательное хозяйство" },
    { id: 63, text: "Какие документы не составляются при планировании ремонтных работ:", options: ["План производства товарной продукции.", "Дефектная ведомость работ;", "График планово-предупредительных ремонтов;", "Смета на капитальный ремонт;", "План работ по совершенствованию ремонтной службы;"], correct: 0, topic: "Ремонтное хозяйство" },
    { id: 64, text: "Общая сумма амортизационных отчислений за весь срок службы оборудования представляет собой:", options: ["Сумму первоначальной стоимости и затрат на ремонт и модернизацию основных производственных фондов за вычетом ликвидационной стоимости;", "Сумму первоначальной стоимости и затрат на ремонт и модернизацию основных производственных фондов;", "Сумму физического и морального износа за весь срок службы оборудования;", "Произведение первоначальной стоимости основных производственных фондов и годовой нормы амортизации;", "Разность между первоначальной и ликвидационной стоимостями основных производственных фондов;"], correct: 0, topic: "Амортизация" },
    { id: 65, text: "Текущий ремонт машин и оборудования представляет собой:", options: ["Устранение мелких неполадок, случайных повреждений, замену деталей с наиболее коротким сроком службы;", "Частичную разборку отдельных узлов и аппаратов, смену деталей с большим сроком службы;", "Полную разборку аппарата с заменой всех износившихся узлов;", "Полную разборку аппарата с заменой всех износившихся узлов и внесение в конструкцию аппарата изменений, повышающих его мощность, уровень механизации и автоматизации;", "Устранение мелких неполадок во время работы оборудования, уточнение физического объема предстоящих ремонтных работ;"], correct: 0, topic: "Ремонт" },
    { id: 66, text: "Капитальный ремонт машин и оборудования представляет собой:", options: ["Полную разборку аппарата с заменой всех износившихся узлов.", "Частичную разборку отдельных узлов и аппаратов, смену деталей с большим сроком службы;", "Устранение мелких неполадок, случайных повреждений, замену деталей с наиболее коротким сроком службы;", "Полную разборку аппарата с заменой всех износившихся узлов и внесение в конструкцию аппарата изменений, повышающих его мощность, уровень механизации и автоматизации;", "Устранение мелких неполадок во время работы оборудования, уточнение физического объема предстоящих ремонтных работ;"], correct: 0, topic: "Ремонт" },
    { id: 67, text: "Амортизация представляет собой:", options: ["Процесс планомерного возмещения износа основных производственных фондов путем перенесения утраченной ими стоимости на стоимость изготавливаемой продукции;", "Процесс единовременного возмещения восстановительной стоимости основных производственных фондов путем перенесения утраченной ими стоимости на стоимость изготавливаемой продукции;", "Процесс начисления морального износа основных производственных фондов на себестоимость изготавливаемой продукции;", "Процесс переоценки основных производственных фондов, учитывающей темпы роста цен и научно-технического прогресса;", "Процесс планомерного возмещения остаточной стоимости основных производственных фондов на стоимость изготавливаемой продукции;"], correct: 0, topic: "Амортизация" },
    { id: 68, text: "Ускоренная амортизация представляет собой:", options: ["Увеличение годовой нормы амортизации не более, чем в два раза;", "Увеличение годовой нормы амортизации более, чем в два раза;", "Увеличение годовой нормы амортизации в пять раз;", "Увеличение годовой нормы амортизации по усмотрению руководства предприятия;", "Увеличение годовой нормы амортизации от двух до пяти раз;"], correct: 0, topic: "Амортизация" },
    { id: 69, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Фондовооруженость труда составит:", options: ["33,14", "0,03;", "3,28;", "45,74;", "19,89"], correct: 0, topic: "Основные фонды" },
    { id: 70, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Фондоотдача (р./р.) составит:", options: ["3,28;", "0,02;", "0,3", "45,74;", "2,05;"], correct: 0, topic: "Основные фонды" },
    { id: 71, text: "Ремонтный цикл – это:", options: ["Время между двумя капитальными ремонтами;", "Время между двумя текущими ремонтами;", "Время между двумя средними ремонтами;", "Продолжительность проведения одного текущего ремонта;", "Продолжительность проведения одного среднего ремонта;", "Продолжительность проведения одного капитального ремонта;"], correct: 0, topic: "Ремонт" },
    { id: 72, text: "Межремонтный пробег оборудования– это:", options: ["Время между двумя очередными ремонтами;", "Время между двумя текущими ремонтами;", "Время между двумя средними ремонтами;", "Продолжительность проведения одного текущего ремонта;", "Продолжительность проведения одного среднего ремонта;", "Время между двумя капитальными ремонтами;", "Продолжительность проведения одного капитального ремонта;"], correct: 0, topic: "Ремонт" },
    { id: 73, text: "Фондоотдача представляет собой:", options: ["Отношение количества выпускаемой продукции к среднегодовой стоимости основных производственных фондов;", "Отношение среднегодовой стоимости основных производственных фондов к объему выпускаемой продукции;", "Отношение прибыли от реализации продукции к среднегодовой стоимости основных производственных фондов;", "Отношение количества выпускаемой продукции к ее себестоимости;", "Отношение первоначальной стоимости основных производственных фондов к их остаточной стоимости;"], correct: 0, topic: "Основные фонды" },
    { id: 74, text: "Фондоемкость представляет собой:", options: ["Отношение среднегодовой стоимости основных производственных фондов к объему выпускаемой продукции;", "Отношение количества выпускаемой продукции к среднегодовой стоимости основных производственных фондов;", "Отношение среднегодовой стоимости основных производственных фондов к прибыли от реализации продукции;", "Отношение количества выпускаемой продукции к ее себестоимости;", "Отношение стоимости введенных основных производственных фондов к их стоимости на конец периода;"], correct: 0, topic: "Основные фонды" },
    { id: 75, text: "Коэффициент износа основных производственных фондов - это:", options: ["Отношение суммы начисленного физического износа основных производственных фондов к их первоначальной стоимости.", "Отношение первоначальной стоимости основных производственных фондов к остаточной стоимости;", "Отношение остаточной стоимости основных производственных фондов к первоначальной стоимости;", "Отношение первоначальной стоимости основных производственных фондов к восстановительной стоимости;", "Отношение суммы начисленного физического износа основных производственных фондов к их остаточной стоимости;"], correct: 0, topic: "Основные фонды" },
    { id: 76, text: "Коэффициент годности основных производственных фондов - это:", options: ["Отношение остаточной стоимости основных производственных фондов к их первоначальной стоимости;", "Отношение первоначальной стоимости основных производственных фондов к остаточной стоимости;", "Отношение первоначальной стоимости основных производственных фондов к их восстановительной стоимости;", "Отношение суммы начисленного физического износа основных производственных фондов к их остаточной стоимости;", "Отношение суммы начисленного физического износа основных производственных фондов к их первоначальной стоимости;"], correct: 0, topic: "Основные фонды" },
    { id: 77, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Фондоемкость (р./р.) составит:", options: ["0.3", "0.02;", "3.28;", "45.74;", "2.05;"], correct: 0, topic: "Основные фонды" },
    { id: 78, text: "Гвозди, болты, наждачная бумага являются:", options: ["Предметами труда;", "Средствами труда;", "Рабочей силой;", "Предметами потребления;"], correct: 0, topic: "Оборотные средства" },
    { id: 79, text: "К основному капиталу относят:", options: ["Экскаватор;", "Дизельное топливо;", "Лопаты;", "Крепежные материалы;"], correct: 0, topic: "Основные фонды" },
    { id: 80, text: "Что из нижеперечисленного входит в состав основных производственных фондов?", options: ["Станки, реакторы, ректификационные колонны;", "Сырье и основные материалы;", "Природные ресурсы;", "Заработная плата основных производственных рабочих;", "Санаторий - профилактиторий, поликлиника, находящиеся на балансе промышленного предприятия;"], correct: 0, topic: "Основные фонды" },
    { id: 81, text: "Какой из перечисленных элементов не входит в состав основных производственных фондов?", options: ["Калькуляторы, канцелярские товары, применяемые в службе управления.", "Здания, сооружения;", "Насосы, двигатели, трансформаторы;", "Линии связи, электропередач, дороги, мосты;", "Столы, стулья, шкафы;"], correct: 0, topic: "Основные фонды" },
    { id: 82, text: "Первоначальная стоимость основных производственных фондов представляет собой:", options: ["Стоимость покупки или изготовления основных производственных фондов с учетом затрат на их доставку, монтаж и хранение.", "Разность между восстановительной стоимостью и суммой морального износа;", "Сумма восстановительной стоимости и величины физического износа;", "Стоимость основных производственных фондов после их переоценки с учетом затрат на их доставку, монтаж и хранение;", "Стоимость покупки или изготовления основных производственных фондов;"], correct: 0, topic: "Основные фонды" },
    { id: 83, text: "Восстановительная стоимость основных производственных фондов представляет собой:", options: ["Стоимость воспроизводства тех же видов основных производственных фондов в условиях текущего периода;", "Разность между первоначальной стоимостью и суммой физического износа;", "Сумма первоначальной стоимости и величин физического и морального износа;", "Стоимость основных производственных фондов с учетом затрат на их ремонт и модернизацию;", "Стоимость покупки или изготовления основных производственных фондов с учетом затрат на их доставку, монтаж и хранение"], correct: 0, topic: "Основные фонды" },
    { id: 84, text: "Остаточная стоимость основных производственных фондов представляет собой:", options: ["Разность между первоначальной стоимостью и суммой физического износа;", "Сумма первоначальной стоимости и величины физического износа;", "Стоимость основных производственных фондов после их ликвидации;", "Стоимость покупки или изготовления основных производственных фондов в ценах и условиях будущего периода;", "Стоимость покупки или изготовления основных производственных фондов с учетом затрат на их доставку, монтаж и хранение за вычетом величины физического износа;"], correct: 0, topic: "Основные фонды" },
    { id: 85, text: "∑((R_t − З_t) / (1+e)^t) - это формула расчета:", options: ["Чистого дисконтированного дохода;", "Индекса доходности;", "Внутренней нормы доходности;", "Приведенных затрат;", "Абсолютной эффективности капитальных вложений;"], correct: 0, topic: "Инвестиции" },
    { id: 86, text: "По проекту количество производимой продукции составит 80 тыс.т., цена продукции – 6500 р./т, себестоимость единицы продукции – 5000 р./т. Капитальные вложения на реализацию проекта – 300 млн.р. Статический срок окупаемости капитальных вложений (г.) составит:", options: ["2,5", "0,4", "1,73", "1,33", "0,58"], correct: 0, topic: "Инвестиции" },
    { id: 87, text: "Инвестиции, осуществляемые с целью расширения объема применяемого физического капитала, можно отнести к:", options: ["Инвестициям в основной капитал;", "Индуцированным инвестициям;", "Инвестициям в запасы;", "Портфельным инвестициям"], correct: 0, topic: "Инвестиции" },
    { id: 88, text: "По проекту количество производимой продукции составит 80 тыс.т., цена продукции – 6500 р./т, себестоимость единицы продукции – 5000 р./т. Капитальные вложения на реализацию проекта – 300 млн.р. Приведенные затраты (тыс.р.) составят:", options: ["400045", "50", "120045", "700000", "5000,6"], correct: 0, topic: "Инвестиции" },
    { id: 89, text: "Показателем сравнительной эффективности капитальных вложений является следующий:", options: ["Приведенные затраты;", "Чистый дисконтированный доход;", "Экономическая эффективность от проведения мероприятия;", "Индекс доходности;", "Внутренняя норма доходности;"], correct: 0, topic: "Инвестиции" },
    { id: 90, text: "∑((R_t − З_t) / (1+e)^t) + ∑((K_t) / (1+e)^t) - это формула расчета:", options: ["Индекса доходности;", "Внутренней нормы доходности;", "Приведенных затрат;", "Чистого дисконтированного дохода;", "Абсолютной эффективности капитальных вложений;"], correct: 0, topic: "Инвестиции" },
    { id: 91, text: "Абсолютная эффективность капитальных вложений, определяемая на уровне предприятия, рассчитывается следующим образом:", options: ["Отношение прироста прибыли, полученного в результате реализации организационно-технического мероприятия, к сумме капитальных вложений, вызвавших этот прирост;", "Отношение суммы капитальных вложений к приросту прибыли, полученному в результате реализации организационно-технического мероприятия;", "Разность между приведенными затратами, имеющими место до и после проведения организационно-технического мероприятия;", "Отношение дисконтированной суммы прибыли к дисконтированной сумме капитальных вложений;", "Разность между дисконтированной суммой результата и дисконтированной суммой затрат, полученными в результате проведения организационно- технического мероприятия;"], correct: 0, topic: "Инвестиции" },
    { id: 92, text: "Приведение результата от внедрения проект и затрат на реализацию проекта, к начальному моменту времени называется:", options: ["Дисконтированием;", "Процентированием;", "Ранжированием;", "Оценкой риска проекта;", "Инвестированием"], correct: 0, topic: "Инвестиции" },
    { id: 93, text: "По проекту количество производимой продукции составит 80 тыс.т., цена продукции – 6500 р/т, себестоимость единицы продукции – 5000 р./т. Капитальные вложения на реализацию проекта – 300 млн.р. Абсолютная эффективность капитальных вложений (р./р.) составит:", options: ["0,4", "2,5", "1,73", "1,33", "0,58"], correct: 0, topic: "Инвестиции" },
    { id: 94, text: "Какие функции не присущи управлению производственно-хозяйственной деятельностью?", options: ["Резервирование;", "Планирование;", "Организация;", "Мотивация;", "Контроль;", "Нормирование;"], correct: 0, topic: "Управление" },
    { id: 95, text: "Какие виды деятельности не характеризуют вспомогательное производство?", options: ["Преобразование исходных товарно-материальные ценности в готовую продукцию с помощью средств производства и рабочей силы;", "Обеспечение в работоспособном состоянии оборудования;", "Транспортировка материальных ресурсов и готовой продукции;", "Контроль за качеством вовлекаемых в производственный процесс материальных ресурсов;"], correct: 0, topic: "Вспомогательное производство" },
    { id: 96, text: "Завершающей производственной процедурой, направленной на разработку плана мероприятий по предупреждению и устранению возможных отклонений и сбоев в производственном процессе является:", options: ["Регулирование;", "Координация;", "Контроль;", "Организация производства;", "Нормирование;"], correct: 0, topic: "Управление" },
    { id: 97, text: "По каким направлениям не осуществляется управление персоналом предприятия:", options: ["Административное.", "Экономическое;", "Научно-техническое;", "Производственной;", "Социальное;"], correct: 0, topic: "Управление персоналом" },
    { id: 98, text: "Основное производство характеризует процесс, в результате которого:", options: ["Исходные товарно-материальные ценности с помощью средств производства и рабочей силы превращаются в готовую продукцию;", "Поддерживаться в работоспособном состоянии оборудование;", "Обеспечивается транспортировка материальных ресурсов и готовой продукции;", "Осуществляется контроль за качеством вовлекаемых в производственный процесс материальных ресурсов;"], correct: 0, topic: "Производство" },
    { id: 99, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Фондоотдача (р./р.) составит:", options: ["3,28;", "0,02;", "0,3", "45,74;", "2,05;"], correct: 0, topic: "Основные фонды" },
    { id: 100, text: "Фондоемкость представляет собой:", options: ["Отношение среднегодовой стоимости основных производственных фондов к объему выпускаемой продукции;", "Отношение количества выпускаемой продукции к среднегодовой стоимости основных производственных фондов;", "Отношение среднегодовой стоимости основных производственных фондов к прибыли от реализации продукции;", "Отношение количества выпускаемой продукции к ее себестоимости;", "Отношение стоимости введенных основных производственных фондов к их стоимости на конец периода;"], correct: 0, topic: "Основные фонды" },
    { id: 101, text: "Коэффициент годности основных производственных фондов - это:", options: ["Отношение остаточной стоимости основных производственных фондов к их первоначальной стоимости;", "Отношение первоначальной стоимости основных производственных фондов к остаточной стоимости;", "Отношение первоначальной стоимости основных производственных фондов к их восстановительной стоимости;", "Отношение суммы начисленного физического износа основных производственных фондов к их остаточной стоимости;", "Отношение суммы начисленного физического износа основных производственных фондов к их первоначальной стоимости;"], correct: 0, topic: "Основные фонды" },
    { id: 102, text: "Коэффициент износа основных производственных фондов - это:", options: ["Отношение суммы начисленного физического износа основных производственных фондов к их первоначальной стоимости.", "Отношение первоначальной стоимости основных производственных фондов к остаточной стоимости;", "Отношение остаточной стоимости основных производственных фондов к первоначальной стоимости;", "Отношение первоначальной стоимости основных производственных фондов к восстановительной стоимости;", "Отношение суммы начисленного физического износа основных производственных фондов к их остаточной стоимости;"], correct: 0, topic: "Основные фонды" },
    { id: 103, text: "Фондоотдача представляет собой:", options: ["Отношение количества выпускаемой продукции к среднегодовой стоимости основных производственных фондов;", "Отношение среднегодовой стоимости основных производственных фондов к объему выпускаемой продукции;", "Отношение прибыли от реализации продукции к среднегодовой стоимости основных производственных фондов;", "Отношение количества выпускаемой продукции к ее себестоимости;", "Отношение первоначальной стоимости основных производственных фондов к их остаточной стоимости;"], correct: 0, topic: "Основные фонды" },
    { id: 104, text: "Ремонтный цикл – это:", options: ["Время между двумя капитальными ремонтами;", "Время между двумя текущими ремонтами;", "Время между двумя средними ремонтами;", "Продолжительность проведения одного текущего ремонта;", "Продолжительность проведения одного среднего ремонта;"], correct: 0, topic: "Ремонт" },
    { id: 105, text: "Межремонтный пробег оборудования– это:", options: ["Время между двумя очередными ремонтами;", "Время между двумя текущими ремонтами;", "Время между двумя средними ремонтами;", "Продолжительность проведения одного текущего ремонта;", "Продолжительность проведения одного среднего ремонта;", "Время между двумя капитальными ремонтами;", "Продолжительность проведения одного капитального ремонта;"], correct: 0, topic: "Ремонт" },
    { id: 106, text: "Текущий ремонт машин и оборудования представляет собой:", options: ["Устранение мелких неполадок, случайных повреждений, замену деталей с наиболее коротким сроком службы;", "Частичную разборку отдельных узлов и аппаратов, смену деталей с большим сроком службы;", "Полную разборку аппарата с заменой всех износившихся узлов;", "Полную разборку аппарата с заменой всех износившихся узлов и внесение в конструкцию аппарата изменений, повышающих его мощность, уровень механизации и автоматизации;", "Устранение мелких неполадок во время работы оборудования, уточнение физического объема предстоящих ремонтных работ;"], correct: 0, topic: "Ремонт" },
    { id: 107, text: "Капитальный ремонт машин и оборудования представляет собой:", options: ["Полную разборку аппарата с заменой всех износившихся узлов.", "Частичную разборку отдельных узлов и аппаратов, смену деталей с большим сроком службы;", "Устранение мелких неполадок, случайных повреждений, замену деталей с наиболее коротким сроком службы;", "Полную разборку аппарата с заменой всех износившихся узлов и внесение в конструкцию аппарата изменений, повышающих его мощность, уровень механизации и автоматизации;", "Устранение мелких неполадок во время работы оборудования, уточнение физического объема предстоящих ремонтных работ;"], correct: 0, topic: "Ремонт" },
    { id: 108, text: "Ускоренная амортизация представляет собой:", options: ["Увеличение годовой нормы амортизации не более, чем в два раза;", "Увеличение годовой нормы амортизации более, чем в два раза;", "Увеличение годовой нормы амортизации в пять раз;", "Увеличение годовой нормы амортизации по усмотрению руководства предприятия;", "Увеличение годовой нормы амортизации от двух до пяти раз;"], correct: 0, topic: "Амортизация" },
    { id: 109, text: "Амортизация представляет собой:", options: ["Процесс планомерного возмещения износа основных производственных фондов путем перенесения утраченной ими стоимости на стоимость изготавливаемой продукции;", "Процесс единовременного возмещения восстановительной стоимости основных производственных фондов путем перенесения утраченной ими стоимости на стоимость изготавливаемой продукции;", "Процесс начисления морального износа основных производственных фондов на себестоимость изготавливаемой продукции;", "Процесс переоценки основных производственных фондов, учитывающей темпы роста цен и научно-технического прогресса;", "Процесс планомерного возмещения остаточной стоимости основных производственных фондов на стоимость изготавливаемой продукции;"], correct: 0, topic: "Амортизация" },
    { id: 110, text: "Остаточная стоимость основных производственных фондов представляет собой:", options: ["Разность между первоначальной стоимостью и суммой физического износа;", "Сумма первоначальной стоимости и величины физического износа;", "Стоимость основных производственных фондов после их ликвидации;", "Стоимость покупки или изготовления основных производственных фондов в ценах и условиях будущего периода;", "Стоимость покупки или изготовления основных производственных фондов с учетом затрат на их доставку, монтаж и хранение за вычетом величины физического износа;"], correct: 0, topic: "Основные фонды" },
    { id: 111, text: "Общая сумма амортизационных отчислений за весь срок службы оборудования представляет собой:", options: ["Сумму первоначальной стоимости и затрат на ремонт и модернизацию основных производственных фондов за вычетом ликвидационной стоимости;", "Сумму первоначальной стоимости и затрат на ремонт и модернизацию основных производственных фондов;", "Сумму физического и морального износа за весь срок службы оборудования;", "Произведение первоначальной стоимости основных производственных фондов и годовой нормы амортизации;", "Разность между первоначальной и ликвидационной стоимостями основных производственных фондов;"], correct: 0, topic: "Амортизация" },
    { id: 112, text: "Первоначальная стоимость основных производственных фондов представляет собой:", options: ["Стоимость покупки или изготовления основных производственных фондов с учетом затрат на их доставку, монтаж и хранение.", "Разность между восстановительной стоимостью и суммой морального износа;", "Сумма восстановительной стоимости и величины физического износа;", "Стоимость основных производственных фондов после их переоценки с учетом затрат на их доставку, монтаж и хранение;", "Стоимость покупки или изготовления основных производственных фондов;"], correct: 0, topic: "Основные фонды" },
    { id: 113, text: "Восстановительная стоимость основных производственных фондов представляет собой:", options: ["Стоимость воспроизводства тех же видов основных производственных фондов в условиях текущего периода;", "Разность между первоначальной стоимостью и суммой физического износа;", "Сумма первоначальной стоимости и величин физического и морального износа;", "Стоимость основных производственных фондов с учетом затрат на их ремонт и модернизацию;", "Стоимость покупки или изготовления основных производственных фондов с учетом затрат на их доставку, монтаж и хранение"], correct: 0, topic: "Основные фонды" },
    { id: 114, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Фондоемкость (р./р.) составит:", options: ["0,3", "0,02;", "3,28;", "45,74;", "2,05;"], correct: 0, topic: "Основные фонды" },
    { id: 115, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел. Фондовооруженость труда составит:", options: ["33,14", "0,03;", "3,28;", "45,74;", "19,89"], correct: 0, topic: "Основные фонды" },
    { id: 116, text: "Гвозди, болты, наждачная бумага являются:", options: ["Предметами труда;", "Средствами труда;", "Рабочей силой;", "Предметами потребления;"], correct: 0, topic: "Оборотные средства" },
    { id: 117, text: "К основному капиталу относят:", options: ["Экскаватор;", "Дизельное топливо;", "Лопаты;", "Крепежные материалы;"], correct: 0, topic: "Основные фонды" },
    { id: 118, text: "Какой из перечисленных элементов не входит в состав основных производственных фондов?", options: ["Калькуляторы, канцелярские товары, применяемые в службе управления.", "Здания, сооружения;", "Насосы, двигатели, трансформаторы;", "Линии связи, электропередач, дороги, мосты;", "Столы, стулья, шкафы;"], correct: 0, topic: "Основные фонды" },
    { id: 119, text: "Что из нижеперечисленного входит в состав основных производственных фондов?", options: ["Станки, реакторы, ректификационные колонны;", "Сырье и основные материалы;", "Природные ресурсы;", "Заработная плата основных производственных рабочих;", "Санаторий - профилакторий, поликлиника, находящиеся на балансе промышленного предприятия;"], correct: 0, topic: "Основные фонды" },
    { id: 120, text: "Абсолютная эффективность капитальных вложений, определяемая на уровне предприятия, рассчитывается следующим образом:", options: ["Отношение прироста прибыли, полученного в результате реализации организационно-технического мероприятия, к сумме капитальных вложений, вызвавших этот прирост;", "Отношение суммы капитальных вложений к приросту прибыли, полученному в результате реализации организационно-технического мероприятия;", "Разность между приведенными затратами, имеющими место до и после проведения организационно-технического мероприятия;", "Отношение дисконтированной суммы прибыли к дисконтированной сумме капитальных вложений;", "Разность между дисконтированной суммой результата и дисконтированной суммой затрат, полученными в результате проведения организационно- технического мероприятия;"], correct: 0, topic: "Инвестиции" },
    { id: 121, text: "Источником осуществления инвестиций могут быть: (выберите не менее 2 правильных ответов)", options: ["Средства амортизационного фонда;", "Выпущенные и размещенные облигации;", "Часть прибыли, которую решили раздать акционерам;", "Уставной капитал предприятия;"], correct: [0, 1], topic: "Инвестиции" },
    { id: 122, text: "По проекту количество производимой продукции составит 80 тыс.т., цена продукции – 6500 р./т, себестоимость единицы продукции – 5000 р./т. Капитальные вложения на реализацию проекта – 300 млн.р. Приведенные затраты (тыс.р.) составят:", options: ["400045", "50", "120045", "700000", "5000,6"], correct: 0, topic: "Инвестиции" },
    { id: 123, text: "По проекту количество производимой продукции составит 80 тыс.т., цена продукции – 6500 р/т, себестоимость единицы продукции – 5000 р./т. Капитальные вложения на реализацию проекта – 300 млн.р. Абсолютная эффективность капитальных вложений (р./р.) составит:", options: ["0,4", "2,5", "1,73", "1,33", "0,58"], correct: 0, topic: "Инвестиции" },
    { id: 124, text: "По проекту количество производимой продукции составит 80 тыс.т., цена продукции – 6500 р./т, себестоимость единицы продукции – 5000 р./т. Капитальные вложения на реализацию проекта – 300 млн.р. Статический срок окупаемости капитальных вложений (г.) составит:", options: ["2,5", "0,4", "1,73", "1,33", "0,58"], correct: 0, topic: "Инвестиции" },
    { id: 125, text: "Показателем сравнительной эффективности капитальных вложений является следующий:", options: ["Приведенные затраты;", "Чистый дисконтированный доход;", "Экономическая эффективность от проведения мероприятия;", "Индекс доходности;", "Внутренняя норма доходности;"], correct: 0, topic: "Инвестиции" },
    { id: 126, text: "Приведение результата от внедрения проект и затрат на реализацию проекта, к начальному моменту времени называется:", options: ["Дисконтированием;", "Процентированием;", "Ранжированием;", "Оценкой риска проекта;", "Инвестированием"], correct: 0, topic: "Инвестиции" },
    { id: 127, text: "Инвестиции, осуществляемые с целью расширения объема применяемого физического капитала, можно отнести к:", options: ["Инвестициям в основной капитал;", "Индуцированным инвестициям;", "Инвестициям в запасы;", "Портфельным инвестициям"], correct: 0, topic: "Инвестиции" },
    { id: 128, text: "∑((R_t − З_t) / (1+e)^t) + ∑((K_t) / (1+e)^t) - это формула расчета:", options: ["Индекса доходности;", "Внутренней нормы доходности;", "Приведенных затрат;", "Чистого дисконтированного дохода;", "Абсолютной эффективности капитальных вложений;"], correct: 0, topic: "Инвестиции" },
    { id: 129, text: "Какие виды деятельности не характеризуют вспомогательное производство?", options: ["Преобразование исходных товарно-материальные ценности в готовую продукцию с помощью средств производства и рабочей силы;", "Обеспечение в работоспособном состоянии оборудования;", "Транспортировка материальных ресурсов и готовой продукции;", "Контроль за качеством вовлекаемых в производственный процесс материальных ресурсов;"], correct: 0, topic: "Вспомогательное производство" },
    { id: 130, text: "Какие функции не присущи управлению производственно-хозяйственной деятельностью?", options: ["Резервирование;", "Планирование;", "Организация;", "Мотивация;", "Контроль;", "Нормирование;"], correct: 0, topic: "Управление" },
    { id: 131, text: "Основное производство характеризует процесс, в результате которого:", options: ["Исходные товарно-материальные ценности с помощью средств производства и рабочей силы превращаются в готовую продукцию;", "Поддерживаться в работоспособном состоянии оборудование;", "Обеспечивается транспортировка материальных ресурсов и готовой продукции;", "Осуществляется контроль за качеством вовлекаемых в производственный процесс материальных ресурсов;"], correct: 0, topic: "Производство" },
    { id: 132, text: "Какие типы социально-трудовых отношений не существуют:", options: ["Ответственность", "Социальное партнерство;", "Солидарность;", "Дискриминация;", "Конфликт;", "Субсидиарность;"], correct: 0, topic: "Социально-трудовые отношения" },
    { id: 133, text: "Завершающей производственной процедурой, направленной на разработку плана мероприятий по предупреждению и устранению возможных отклонений и сбоев в производственном процессе является:", options: ["Регулирование;", "Координация;", "Контроль;", "Организация производства;", "Нормирование;"], correct: 0, topic: "Управление" },
    { id: 134, text: "По каким направлениям не осуществляется управление персоналом предприятия:", options: ["Административное.", "Экономическое;", "Научно-техническое;", "Производственной;", "Социальное;"], correct: 0, topic: "Управление персоналом" },
    { id: 135, text: "К источникам формирования оборотных средств не относятся:", options: ["Личные сбережения работников предприятия, находящиеся на депозитных счетах в банке;", "Минимальная задолженность предприятия по заработной плате перед своими работниками;", "Минимальная задолженность предприятия перед пенсионным фондом;", "Заемные средства;", "Минимальная задолженность предприятия перед фондом обязательного медицинского страхования;"], correct: 0, topic: "Оборотные средства" },
    { id: 136, text: "К оборотному капиталу относят:", options: ["Топливо;", "Дорогостоящие инструменты;", "Сооружения;", "Рабочий скот;"], correct: 0, topic: "Оборотные средства" },
    { id: 137, text: "Текущий запас оборотных средств предназначен для следующих целей:", options: ["Повседневного использования в производственном процессе.", "Расходования в процессе производства продукции в случае непредвиденной задержки поставок;", "Складской обработки и подготовки к отпуску материального ресурса;", "Проектирования складских помещений;", "Установления лимита оборотных средств;"], correct: 0, topic: "Оборотные средства" },
    { id: 138, text: "Согласно методу прямого счета, запас оборотных средств включает следующие элементы: (выберите не менее 2 правильных ответов)", options: ["Гарантийный и складской запасы;", "Текущий запас;", "Текущий и подготовительный запасы;", "Гарантийный и страховой запасы;"], correct: [0, 1], topic: "Оборотные средства" },
    { id: 139, text: "Что из нижеперечисленного не входит в состав оборотных средств?", options: ["Многолетние насаждения.", "Сырье и основные материалы;", "Полуфабрикаты;", "Незавершенное производство;", "Расходы будущих периодов;", "Топливо и энергоресурсы;"], correct: 0, topic: "Оборотные средства" },
    { id: 140, text: "Объем реализованной продукции составил 120 млн.р., себестоимость реализованной продукции – 95 млн.р., среднегодовой остаток нормируемых оборотных средств – 15 млн.р., среднегодовая стоимость основных производственных фондов – 300 млн.р. Коэффициент закрепления оборотных средств будет равен:", options: ["0,125", "8", "0,4"], correct: 0, topic: "Оборотные средства" },
    { id: 141, text: "Объем реализованной продукции составил 120 млн.р., себестоимость реализованной продукции – 95 млн.р., среднегодовой остаток нормируемых оборотных средств – 15 млн.р., среднегодовая стоимость основных производственных фондов – 300 млн.р. Длительность одного оборота оборотных средств составит (дн.):", options: ["45", "11,25", "900", "3,75", "240"], correct: 0, topic: "Оборотные средства" },
    { id: 142, text: "Что из нижеперечисленного входит в состав оборотных средств?", options: ["Малоценные и быстроизнашивающиеся предметы.", "Транспортные средства;", "Многолетние насаждения;", "Рабочий и продуктивный скот;", "Линии связи, электропередач;"], correct: 0, topic: "Оборотные средства" },
    { id: 143, text: "Гарантийный запас оборотных средств предназначен для", options: ["Расходования в процессе производства продукции в случае непредвиденной задержки поставок;", "Складской обработки и подготовки к отпуску материального ресурса;", "Проектирования складских помещений;", "Установления лимита оборотных средств;", "Повседневного использования в производственном процессе;"], correct: 0, topic: "Оборотные средства" },
    { id: 144, text: "Длительность одного оборота рассчитывается следующим образом:", options: ["Отношение числа дней в периоде к коэффициенту оборачиваемости;", "Отношение числа дней в периоде к коэффициенту загрузки;", "Отношение коэффициента загрузки к числу дней в периоде;", "Отношение коэффициента оборачиваемости к числу дней в периоде;", "Отношение коэффициента загрузки к коэффициенту оборачиваемости;"], correct: 0, topic: "Оборотные средства" },
    { id: 145, text: "Объем реализованной продукции составил 120 млн.р., себестоимость реализованной продукции – 95 млн.р., среднегодовой остаток нормируемых оборотных средств – 15 млн.р., среднегодовая стоимость основных производственных фондов – 300 млн.р. Коэффициент оборачиваемости оборотных средств будет равен:", options: ["8", "0,4", "0,38", "1,67", "0,125"], correct: 0, topic: "Оборотные средства" },
    { id: 146, text: "Коэффициент оборачиваемости оборотных средств определяется как:", options: ["Отношение объема реализованной продукции к среднегодовому остатку оборотных средств;", "Отношение числа дней в периоде к коэффициенту загрузки оборотных средств;", "Отношение среднегодового остатка оборотных средств к объему реализованной продукции;", "Отношение прибыли от реализации продукции к среднегодовому остатку оборотных средств;", "Отношение прибыли от реализации продукции к себестоимости реализованной продукции;"], correct: 0, topic: "Оборотные средства" },
    { id: 147, text: "Длительность одного оборота рассчитывается следующим образом:", options: ["Отношение числа дней в периоде к коэффициенту оборачиваемости;", "Отношение числа дней в периоде к коэффициенту загрузки;", "Отношение коэффициента загрузки к числу дней в периоде;", "Отношение коэффициента оборачиваемости к числу дней в периоде;", "Отношение коэффициента загрузки к коэффициенту оборачиваемости;"], correct: 0, topic: "Оборотные средства" },
    { id: 148, text: "Объем реализованной продукции составил 120 млн.р., себестоимость реализованной продукции – 95 млн.р., среднегодовой остаток нормируемых оборотных средств – 15 млн.р., среднегодовая стоимость основных производственных фондов – 300 млн.р. Длительность одного оборота оборотных средств составит (дн.):", options: ["45", "11,25", "900", "3,75", "240"], correct: 0, topic: "Оборотные средства" },
    { id: 149, text: "Объем реализованной продукции составил 120 млн.р., себестоимость реализованной продукции – 95 млн.р., среднегодовой остаток нормируемых оборотных средств – 15 млн.р., среднегодовая стоимость основных производственных фондов – 300 млн.р. Коэффициент закрепления оборотных средств будет равен:", options: ["0,125", "8", "0,4", "0,38", "1,67"], correct: 0, topic: "Оборотные средства" },
    { id: 150, text: "Текущий запас оборотных средств предназначен для следующих целей:", options: ["Повседневного использования в производственном процессе.", "Расходования в процессе производства продукции в случае непредвиденной задержки поставок;", "Складской обработки и подготовки к отпуску материального ресурса;", "Проектирования складских помещений;", "Установления лимита оборотных средств;"], correct: 0, topic: "Оборотные средства" },
    { id: 151, text: "Объем реализованной продукции составил 120 млн.р., себестоимость реализованной продукции – 95 млн.р., среднегодовой остаток нормируемых оборотных средств – 15 млн.р., среднегодовая стоимость основных производственных фондов – 300 млн.р. Коэффициент оборачиваемости оборотных средств будет равен:", options: ["8", "0,4", "0,38", "1,67", "0,125"], correct: 0, topic: "Оборотные средства" },
    { id: 152, text: "К оборотному капиталу относят:", options: ["Топливо;", "Дорогостоящие инструменты;", "Сооружения;", "Рабочий скот;"], correct: 0, topic: "Оборотные средства" },
    { id: 153, text: "Гарантийный запас оборотных средств предназначен для", options: ["Расходования в процессе производства продукции в случае непредвиденной задержки поставок;", "Складской обработки и подготовки к отпуску материального ресурса;", "Проектирования складских помещений;", "Установления лимита оборотных средств;", "Повседневного использования в производственном процессе;"], correct: 0, topic: "Оборотные средства" },
    { id: 154, text: "К источникам формирования оборотных средств не относятся:", options: ["Личные сбережения работников предприятия, находящиеся на депозитных счетах в банке;", "Минимальная задолженность предприятия по заработной плате перед своими работниками;", "Минимальная задолженность предприятия перед пенсионным фондом;", "Заемные средства;", "Минимальная задолженность предприятия перед фондом обязательного медицинского страхования;"], correct: 0, topic: "Оборотные средства" },
    { id: 155, text: "Согласно методу прямого счета, запас оборотных средств включает следующие элементы: (выберите не менее 2 правильных ответов)", options: ["Гарантийный и складской запасы;", "Текущий запас;", "Текущий и подготовительный запасы;", "Гарантийный и страховой запасы;"], correct: [0, 1], topic: "Оборотные средства" },
    { id: 156, text: "Что из нижеперечисленного не входит в состав оборотных средств?", options: ["Многолетние насаждения.", "Сырье и основные материалы;", "Полуфабрикаты;", "Незавершенное производство;", "Расходы будущих периодов;"], correct: 0, topic: "Оборотные средства" },
    { id: 157, text: "Коэффициент оборачиваемости оборотных средств определяется как:", options: ["Отношение объема реализованной продукции к среднегодовому остатку оборотных средств;", "Отношение числа дней в периоде к коэффициенту загрузки оборотных средств;", "Отношение среднегодового остатка оборотных средств к объему реализованной продукции;", "Отношение прибыли от реализации продукции к среднегодовому остатку оборотных средств;", "Отношение прибыли от реализации продукции к себестоимости реализованной продукции;"], correct: 0, topic: "Оборотные средства" },
    { id: 158, text: "Производительность реактора по сырью – 12,5т/ч, выход готовой продукции – 80%, в цехе установлено 2 реактора, производство непрерывное, простои оборудования на ремонт – 15 дн. Производственная мощность (тыс.т) составит:", options: ["168", "210", "8,75", "7", "262,5"], correct: 0, topic: "Производственная мощность" },
    { id: 159, text: "Реализованную продукцию можно рассчитать следующим образом:", options: ["Из товарной продукции вычесть разность остатков полуфабрикатов на конец и начало года;", "Разность между товарной продукцией и суммой остатков полуфабрикатов на начало и конец года;", "Из товарной продукции вычесть разность остатков готовой продукции на складах на конец и начало года", "К товарной продукции прибавить разность остатков готовой продукции на складах на конец и начало года;", "Из товарной продукции вычесть материальные и приравненные к ним затраты;"], correct: 0, topic: "Объем производства" },
    { id: 160, text: "Товарную продукцию можно рассчитать следующим образом:", options: ["Из валовой продукции вычесть разность остатков полуфабрикатов на конец и начало года;", "Разность между валовой продукцией и суммой остатков полуфабрикатов на конец и начало года;", "Разность между валовым оборотом и внутризаводским оборотом;", "К валовой продукции прибавить разность остатков готовой продукции на складах на начало и конец года;", "Из валовой продукции вычесть материальные и приравненные к ним затраты;"], correct: 0, topic: "Объем производства" },
    { id: 161, text: "Производственная мощность представляет собой:", options: ["Максимально возможный годовой выпуск продукции в натуральном выражении при полном использовании оборудования с учетом достижений передовой техники, технологии и организации производства.", "Максимально возможный выпуск продукции в час или в смену в натуральном выражении при полном использовании оборудования с учетом достижений передовой техники, технологии и организации производства;", "Максимально возможная загрузка аппарата за один производственный цикл в натуральном выражении при полном использовании оборудования с учетом достижений передовой техники, технологии и организации производства;", "Максимально возможный выход готовой продукции из сырья (в долях единиц) при полном использовании оборудования с учетом достижений передовой техники, технологии и организации производства;", "Максимально возможный эффективный фонд времени работы оборудования с учетом достижений передовой техники, технологии и организации производства;"], correct: 0, topic: "Производственная мощность" },
    { id: 162, text: "Производственная мощность рассчитывается как:", options: ["Произведение производительности оборудования, эффективного фонда времени оборудования и количества однотипных единиц оборудования;", "Сумма производительности оборудования, времени работы и количества однотипных единиц оборудования;", "Произведение производительности оборудования, календарного фонда времени оборудования и количества однотипных единиц оборудования;", "Произведение производительности оборудования, количества однотипных единиц оборудования и времени простоя оборудования во всех видах ремонта;", "Произведение эффективного фонда времени оборудования, количества однотипных единиц оборудования и доли выхода готовой продукции;"], correct: 0, topic: "Производственная мощность" },
    { id: 163, text: "Производительность реактора по сырью – 12,5т/ч, выход готовой продукции – 80%, в цехе установлено 2 реактора, производство непрерывное, простои оборудования на ремонт – 15 дн. Производственная мощность (тыс.т) составит:", options: ["168", "210", "8,75", "7", "262,5"], correct: 0, topic: "Производственная мощность" },
    { id: 164, text: "Товарную продукцию можно рассчитать следующим образом:", options: ["Из валовой продукции вычесть разность остатков полуфабрикатов на конец и начало года;", "Разность между валовой продукцией и суммой остатков полуфабрикатов на конец и начало года;", "Разность между валовым оборотом и внутризаводским оборотом;", "К валовой продукции прибавить разность остатков готовой продукции на складах на начало и конец года;", "Из валовой продукции вычесть материальные и приравненные к ним затраты;"], correct: 0, topic: "Объем производства" },
    { id: 165, text: "Производственная мощность рассчитывается как:", options: ["Произведение производительности оборудования, эффективного фонда времени оборудования и количества однотипных единиц оборудования;", "Сумма производительности оборудования, времени работы и количества однотипных единиц оборудования;", "Произведение производительности оборудования, календарного фонда времени оборудования и количества однотипных единиц оборудования;", "Произведение производительности оборудования, количества однотипных единиц оборудования и времени простоя оборудования во всех видах ремонта;", "Произведение эффективного фонда времени оборудования, количества однотипных единиц оборудования и доли выхода готовой продукции;"], correct: 0, topic: "Производственная мощность" },
    { id: 166, text: "Производственная мощность представляет собой:", options: ["Максимально возможный годовой выпуск продукции в натуральном выражении при полном использовании оборудования с учетом достижений передовой техники, технологии и организации производства.", "Максимально возможный выпуск продукции в час или в смену в натуральном выражении при полном использовании оборудования с учетом достижений передовой техники, технологии и организации производства;", "Максимально возможная загрузка аппарата за один производственный цикл в натуральном выражении при полном использовании оборудования с учетом достижений передовой техники, технологии и организации производства;", "Максимально возможный выход готовой продукции из сырья (в долях единиц) при полном использовании оборудования с учетом достижений передовой техники, технологии и организации производства;", "Максимально возможный эффективный фонд времени работы оборудования с учетом достижений передовой техники, технологии и организации производства;"], correct: 0, topic: "Производственная мощность" },
    { id: 167, text: "Реализованную продукцию можно рассчитать следующим образом:", options: ["Из товарной продукции вычесть разность остатков полуфабрикатов на конец и начало года;", "Разность между товарной продукцией и суммой остатков полуфабрикатов на начало и конец года;", "Из товарной продукции вычесть разность остатков готовой продукции на складах на конец и начало года", "К товарной продукции прибавить разность остатков готовой продукции на складах на конец и начало года;", "Из товарной продукции вычесть материальные и приравненные к ним затраты;"], correct: 0, topic: "Объем производства" },
    { id: 168, text: "Коэффициент внешнего оборота по приему определяется следующим образом:", options: ["Отношение количества принятых на работу людей к численности промышленно-производственного персонала на конец года;", "Отношение количества принятых на работу людей к количеству уволенных людей;", "Отношение количества принятых на работу людей к численности промышленно-производственного персонала на начало года;", "Отношение количества принятых на работу людей к сумме численности уволенных и принятых на работу;", "Как разность между единицей и коэффициентом внешнего оборота по выбытию;"], correct: 0, topic: "Персонал" },
    { id: 169, text: "Коэффициент внешнего оборота по выбытию определяется следующим образом:", options: ["Отношение количества уволенных с предприятия людей к численности промышленно-производственного персонала на начало года;", "Отношение количества уволенных с предприятия людей к количеству принятых на работу;", "Отношение количества уволенных с предприятия людей к численности промышленно-производственного персонала на конец года;", "Отношение количества уволенных с предприятия людей к сумме численности уволенных и принятых на работу;", "Отношение количества уволенных людей с предприятия по собственному желанию и за нарушения трудовой дисциплины к численности промышленно- производственного персонала на начало года;"], correct: 0, topic: "Персонал" },
    { id: 170, text: "Служащие выполняют одну из следующих функций:", options: ["Осуществляют подготовку и оформление производственной документации;", "Непосредственно воздействуют на предмет труда с целью получения готовой продукции;", "Обеспечивают контроль за качеством сырья и готовой продукции;", "Осуществляют бухгалтерский учет и аудит на предприятии;", "Координируют деятельность подчиняемых им структурных подразделений;"], correct: 0, topic: "Персонал" },
    { id: 171, text: "Норма времени – это:", options: ["Количество рабочего времени, необходимое для выполнения одной операции или определенной объема работ при данных организационно-технических условиях.", "Количество продукции или объем работ, которые должны быть выполнены на протяжении одного часа;", "Число единиц оборудования, которые должен обслужить один рабочий на протяжении рабочей смены;", "Количество времени, связанное с непосредственным воздействием на предмет труда;", "Аппаратурно-свободное время, которое может быть использовано для обслуживания других аппаратов;"], correct: 0, topic: "Нормирование" },
    { id: 172, text: "Эффективный фонд рабочего времени одного работника определяется следующим образом:", options: ["Разность между номинальным фондом рабочего времени и невыходами на работу по причине отпуска, болезни, выполнения государственных обязанностей;", "Разность между календарным фондом рабочего времени и общим количеством выходных и праздников;", "Разность между календарным фондом рабочего времени и невыходами на работу по причине отпуска, болезни, выполнения государственных обязанностей;", "Разность между календарным и номинальным фондом рабочего времени;", "Сумма номинального фонда рабочего времени и общего количества выходных и праздников;"], correct: 0, topic: "Персонал" },
    { id: 173, text: "По трудоемкости программы списочная численность работников определяется как:", options: ["Отношение планируемого объема выполненных работ к произведению нормы выработки и эффективного фонда рабочего времени;", "Произведение явочной численности рабочих и коэффициента подмены;", "Произведение количества штатных точек и числа смен;", "Разность между списочной численностью и резервом людей, находящихся в входных днях, отпуске, на больничном.", "Отношение количества однотипного оборудования к норме обслуживания;"], correct: 0, topic: "Персонал" },
    { id: 174, text: "Норма обслуживания – это:", options: ["Число единиц оборудования, которые должен обслужить один рабочий на протяжении рабочей смены;", "Количество продукции или объем работ, которые должны быть выполнены на протяжении одного часа;", "Количество времени, связанное с непосредственным воздействием на предмет труда;", "Аппаратурно-свободное время, которое может быть использовано для обслуживания других аппаратов;", "Количество рабочего времени, необходимое для выполнения одной операции или определенной объема работ при данных организационно-технических условиях;"], correct: 0, topic: "Нормирование" },
    { id: 175, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Производительность труда в натуральном измерении составит:", options: ["0,72;", "14,5;", "1,38;", "19,9", "108,7;"], correct: 0, topic: "Производительность труда" },
    { id: 176, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р., среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Производительность труда в стоимостном измерении составит:", options: ["108,7.", "14,5;", "1,38;", "19,9", "0,72;"], correct: 0, topic: "Производительность труда" },
    { id: 177, text: "Норма выработки – это:", options: ["Количество продукции или объем работ, которые должны быть выполнены на протяжении одного часа или смены;", "Число единиц оборудования, которые должен обслужить один рабочий на протяжении рабочей смены;", "Количество времени, связанное с непосредственным воздействием на предмет труда;", "Аппаратурно-свободное время, которое может быть использовано для обслуживания других аппаратов;", "Количество рабочего времени, необходимое для выполнения одной операции или определенной объема работ при данных организационно-технических условиях;"], correct: 0, topic: "Нормирование" },
    { id: 178, text: "По расстановочному штату явочная численность работников определяется как:", options: ["Отношение количества однотипного оборудования к норме обслуживания.", "Отношение планируемого объема выполненных работ к произведению нормы выработки и эффективного фонда рабочего времени;", "Отношение произведения объема выпущенной продукции и нормы времени к эффективному фонду рабочего времени;", "Произведение количества штатных точек и числа смен;", "Разность между списочной численностью и резервом людей, находящихся на выходных днях, отпуске, больничном;"], correct: 0, topic: "Персонал" },
    { id: 179, text: "В соответствии с общероссийским классификатором профессий какие выделяют группы работников?", options: ["Рабочие, служащие, специалисты и руководители;", "Основные рабочие, вспомогательные рабочие, специалисты и руководители;", "Рабочие, служащие, специалисты и младший обслуживающий персонал;", "Основные рабочие, вспомогательные рабочие, инженерно-технические работники и младший обслуживающий персонал;", "Охрана, инженерно-технические работники, служащие и младший обслуживающий персонал;"], correct: 0, topic: "Персонал" },
    { id: 180, text: "Основные рабочие выполняют одну из следующих функций:", options: ["Управляют процессом производства продукции;", "Обеспечивают ремонт контрольно-измерительных приборов, используемых в основном производстве;", "Заполняют табель учета рабочего времени;", "Разрабатывают график планово-предупредительных ремонтных работ оборудования;", "Разрабатывают план материально-технического снабжения производства;"], correct: 0, topic: "Персонал" },
    { id: 181, text: "Вспомогательные рабочие выполняют одну из следующих функций:", options: ["Осуществляют транспортировку, складирование готовой продукции;", "Управляют процессом производства продукции;", "Осуществляют подготовку и оформление документации, учет и контроль;", "Разрабатывают технологический регламент производства продукции;", "Обрабатывают информацию для перевода ее с бумажного на электронный носитель;"], correct: 0, topic: "Персонал" },
    { id: 182, text: "На основе данных таблицы 2 определить эффективный фонд рабочего времени (дн.). Для работника установлен сменный режим работы, на подмену определена 1 бригада. Таблица 2 <Продолжительность смены, час: 8; Норма обслуживания, аппарат/чел: 3; Число обслуживаемых аппаратов: 12; Число дней отпуска, дн.: 24; Число дней болезни, дн.: 3; Число дней ученического отпуска, дн.: 2; Количество праздников, дн.: 15.>", options: ["245;", "321", "230;", "175;", "190;"], correct: 0, topic: "Персонал" },
    { id: 183, text: "По расстановочному штату явочная численность работников определяется как:", options: ["Отношение количества однотипного оборудования к норме обслуживания.", "Отношение планируемого объема выполненных работ к произведению нормы выработки и эффективного фонда рабочего времени;", "Отношение произведения объема выпущенной продукции и нормы времени к эффективному фонду рабочего времени;", "Произведение количества штатных точек и числа смен;", "Разность между списочной численностью и резервом людей, находящихся на выходных днях, отпуске, больничном;"], correct: 0, topic: "Персонал" },
    { id: 184, text: "Основные рабочие выполняют одну из следующих функций:", options: ["Управляют процессом производства продукции;", "Обеспечивают ремонт контрольно-измерительных приборов, используемых в основном производстве;", "Заполняют табель учета рабочего времени;", "Разрабатывают график планово-предупредительных ремонтных работ оборудования;", "Разрабатывают план материально-технического снабжения производства;"], correct: 0, topic: "Персонал" },
    { id: 185, text: "Служащие выполняют одну из следующих функций:", options: ["Осуществляют подготовку и оформление производственной документации;", "Непосредственно воздействуют на предмет труда с целью получения готовой продукции;", "Обеспечивают контроль за качеством сырья и готовой продукции;", "Осуществляют бухгалтерский учет и аудит на предприятии;", "Координируют деятельность подчиняемых им структурных подразделений;"], correct: 0, topic: "Персонал" },
    { id: 186, text: "Вспомогательные рабочие выполняют одну из следующих функций:", options: ["Осуществляют транспортировку, складирование готовой продукции;", "Управляют процессом производства продукции;", "Осуществляют подготовку и оформление документации, учет и контроль;", "Разрабатывают технологический регламент производства продукции;"], correct: 0, topic: "Персонал" },
    { id: 187, text: "Коэффициент внешнего оборота по приему определяется следующим образом:", options: ["Отношение количества принятых на работу людей к численности промышленно-производственного персонала на конец года;", "Отношение количества принятых на работу людей к количеству уволенных людей;", "Отношение количества принятых на работу людей к численности промышленно-производственного персонала на начало года;", "Отношение количества принятых на работу людей к сумме численности уволенных и принятых на работу;", "Как разность между единицей и коэффициентом внешнего оборота по выбытию;"], correct: 0, topic: "Персонал" },
    { id: 188, text: "Коэффициент текучести кадров определяется следующим образом:", options: ["Отношение количества уволенных людей с предприятия по собственному желанию и за нарушения трудовой дисциплины к среднесписочной численности промышленно-производственного персонала.", "Отношение количества уволенных людей с предприятия по причине ухода на пенсию и в связи с призывом в армию к среднесписочной численности промышленно-производственного персонала;", "Отношение количества уволенных с предприятия людей к численности промышленно-производственного персонала на конец года;", "Отношение количества уволенных с предприятия людей к численности промышленно-производственного персонала на начало года;", "Отношение количества уволенных с предприятия людей к сумме численности уволенных и принятых на работу;"], correct: 0, topic: "Персонал" },
    { id: 189, text: "Коэффициент внешнего оборота по выбытию определяется следующим образом:", options: ["Отношение количества уволенных с предприятия людей к численности промышленно-производственного персонала на начало года;", "Отношение количества уволенных с предприятия людей к количеству принятых на работу;", "Отношение количества уволенных с предприятия людей к численности промышленно-производственного персонала на конец года;", "Отношение количества уволенных с предприятия людей к сумме численности уволенных и принятых на работу;", "Отношение количества уволенных людей с предприятия по собственному желанию и за нарушения трудовой дисциплины к численности промышленно- производственного персонала на начало года;"], correct: 0, topic: "Персонал" },
    { id: 190, text: "Коэффициент стабильности кадров определяется следующим образом:", options: ["Как разность между единицей и коэффициентами внешнего оборота по приему и выбытию;", "Как обратная величина коэффициента текучести кадров;", "Как сумма коэффициентов внешнего оборота по приему и выбытию;", "Отношение количества коэффициента внешнего оборота по выбытию к коэффициенту внешнего оборота по приему;"], correct: 0, topic: "Персонал" },
    { id: 191, text: "Производительность труда определяется как:", options: ["Отношение количества изготовленной продукции к численности персонала;", "Отношение численности персонала к количеству изготовленной продукции;", "Отношение количества затраченного времени в человеко-часах к количеству изготовленной продукции;", "Отношение численности персонала к среднегодовой стоимости основных производственных фондов;", "Отношение среднегодовой стоимости основных производственных фондов к численности персонала;"], correct: 0, topic: "Производительность труда" },
    { id: 192, text: "Какие выделяют методы измерения индивидуальной производительности труда?", options: ["Трудовой, натуральный, стоимостной;", "Временной, стоимостной, натуральный;", "Затратный, рыночный, натуральный;", "Рентный, натуральный, на основе трудоемкости;", "Альтернативный, стоимостной, затратный;"], correct: 0, topic: "Производительность труда" },
    { id: 193, text: "Норма времени – это:", options: ["Количество рабочего времени, необходимое для выполнения одной операции или определенной объема работ при данных организационно-технических условиях.", "Количество продукции или объем работ, которые должны быть выполнены на протяжении одного часа;", "Число единиц оборудования, которые должен обслужить один рабочий на протяжении рабочей смены;", "Количество времени, связанное с непосредственным воздействием на предмет труда;", "Аппаратурно-свободное время, которое может быть использовано для обслуживания других аппаратов;"], correct: 0, topic: "Нормирование" },
    { id: 194, text: "Норма выработки – это:", options: ["Количество продукции или объем работ, которые должны быть выполнены на протяжении одного часа или смены;", "Число единиц оборудования, которые должен обслужить один рабочий на протяжении рабочей смены;", "Количество времени, связанное с непосредственным воздействием на предмет труда;", "Аппаратурно-свободное время, которое может быть использовано для обслуживания других аппаратов;", "Количество рабочего времени, необходимое для выполнения одной операции или определенной объема работ при данных организационно-технических условиях;"], correct: 0, topic: "Нормирование" },
    { id: 195, text: "Норма обслуживания – это:", options: ["Число единиц оборудования, которые должен обслужить один рабочий на протяжении рабочей смены;", "Количество продукции или объем работ, которые должны быть выполнены на протяжении одного часа;", "Количество времени, связанное с непосредственным воздействием на предмет труда;", "Аппаратурно-свободное время, которое может быть использовано для обслуживания других аппаратов;", "Количество рабочего времени, необходимое для выполнения одной операции или определенной объема работ при данных организационно-технических условиях;"], correct: 0, topic: "Нормирование" },
    { id: 196, text: "Эффективный фонд рабочего времени одного работника определяется следующим образом:", options: ["Разность между номинальным фондом рабочего времени и невыходами на работу по причине отпуска, болезни, выполнения государственных обязанностей;", "Разность между календарным фондом рабочего времени и общим количеством выходных и праздников;", "Разность между календарным фондом рабочего времени и невыходами на работу по причине отпуска, болезни, выполнения государственных обязанностей;", "Разность между календарным и номинальным фондом рабочего времени;", "Сумма номинального фонда рабочего времени и общего количества выходных и праздников;"], correct: 0, topic: "Персонал" },
    { id: 197, text: "По трудоемкости программы списочная численность работников определяется как:", options: ["Отношение планируемого объема выполненных работ к произведению нормы выработки и эффективного фонда рабочего времени;", "Произведение явочной численности рабочих и коэффициента подмены;", "Произведение количества штатных точек и числа смен;", "Разность между списочной численностью и резервом людей, находящихся в входных днях, отпуске, на больничном.", "Отношение количества однотипного оборудования к норме обслуживания;"], correct: 0, topic: "Персонал" },
    { id: 198, text: "На основе данных таблицы 2 определить списочную численность рабочих. Для работника установлен сменный режим работы, на подмену определена 1 бригада. Таблица 2 <Продолжительность смены, час: 8; Норма обслуживания, аппарат/чел: 3; Число обслуживаемых аппаратов: 12; Число дней отпуска, дн.: 24; Число дней болезни, дн.: 3; Число дней ученического отпуска, дн.: 2; Количество праздников, дн.: 15.>", options: ["18;", "12;", "4;", "6;", "16;"], correct: 0, topic: "Персонал" },
    { id: 199, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р, среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Производительность труда в натуральном измерении составит:", options: ["0,72;", "14,5;", "1,38;", "19,9", "108,7;"], correct: 0, topic: "Производительность труда" },
    { id: 200, text: "Объем реализованной продукции составляет 250 тыс.т, цена продукции – 150 р./т, себестоимость единицы продукции – 130 р./т, прибыль от прочей реализации - 1500 тыс.р., внереализационные доходы с учетом расходов – 350 тыс.р., среднегодовая стоимость основных производственных фондов – 11435 тыс.р., среднегодовой остаток нормируемых оборотных средств – 6861 тыс.р., численность работников предприятия – 345 чел., налог на прибыль – 1370 тыс.р. Производительность труда в стоимостном измерении составит:", options: ["108,7.", "14,5;", "1,38;", "19,9", "0,72;"], correct: 0, topic: "Производительность труда" },
    { id: 201, text: "На основе данных таблицы 2 определить явочную численность рабочих. Для работника установлен сменный режим работы, на подмену определена 1 бригада. Таблица 2 <Продолжительность смены, час: 8; Норма обслуживания, аппарат/чел: 3; Число обслуживаемых аппаратов: 12; Число дней отпуска, дн.: 24; Число дней болезни, дн.: 3; Число дней ученического отпуска, дн.: 2; Количество праздников, дн.: 15.> ", options: ["12;", "18;", "4;", "6;", "16;"], correct: 0, topic: "Персонал" },
    { id: 202, text: "Определить производительность труда по стоимостному методу на основе данных таблицы 1. Таблица 1 <Выпуск цемента, тыс.т (марки М 400 — 250, марки М 500 — 300); Списочное число работников — 600; Цена единицы продукции, руб. (марки М 400 — 100, марки М 500 — 112); Себестоимость продукции, руб. (марки М 400 — 75, марки М 500 — 88).>", options: ["97,7;", "0,92;", "1,09;", "75,25;", "0,01;"], correct: 0, topic: "Производительность труда" },
    { id: 203, text: "В соответствии с общероссийским классификатором профессий какие выделяют группы работников?", options: ["Рабочие, служащие, специалисты и руководители;", "Основные рабочие, вспомогательные рабочие, специалисты и руководители;", "Рабочие, служащие, специалисты и младший обслуживающий персонал;", "Основные рабочие, вспомогательные рабочие, инженерно-технические работники и младший обслуживающий персонал;", "Охрана, инженерно-технические работники, служащие и младший обслуживающий персонал;"], correct: 0, topic: "Персонал" },
    { id: 204, text: "Реальная заработная плата – это:", options: ["Количество товаров и услуг, которые может позволить себе приобрести работник на свой денежный доход;", "Минимально необходимая сумма денежных средств, выплачиваемая работнику для поддержания трудоспособности;", "Количество товаров и услуг, выдаваемых работнику в качестве натуральной оплаты труда;", "Денежная сумма, которую получает работник за работу, выполненную в определенный период времени.", "Выбор максимально возможной суммы денежных средств, полученной работником, из ряда месяцев в течение года;"], correct: 0, topic: "Оплата труда" },
    { id: 205, text: "К системе сдельной формы оплаты труда не относится:", options: ["Сдельно-повременная.", "Простая сдельная;", "Сдельно-премиальная;", "Сдельно-прогрессивная;", "Косвенно-сдельная;"], correct: 0, topic: "Оплата труда" },
    { id: 206, text: "В состав капитальных вложений не входит элемент:", options: ["Затраты на приобретение основных и вспомогательных материалов", "Затраты на строительно-монтажные работы", "Затраты на приобретение оборудования, инструмента, инвентаря", "Затраты на проектно-изыскательные работы", "Затраты на инфраструктуру и охрану окружающей среды"], correct: 0, topic: "Инвестиции" },
    { id: 207, text: "К инвестициям в промышленности не могут быть отнесены:", options: ["Денежные средства, целевые банковские вклады", "Имущественные права, вытекающие из авторского права", "«Ноу-хау», опыт и прочие интеллектуальные ценности", "Акции, облигации и другие ценные бумаги", "Права пользования землей и другими природными ресурсами"], correct: 0, topic: "Инвестиции" },
    { id: 208, text: "Какие виды структуры капитальных вложений названы не верно:", options: ["Внутрипроизводственная", "Воспроизводственная", "Отраслевая", "Территориальная", "Технологическая"], correct: 0, topic: "Инвестиции" },
    { id: 209, text: "При простой сдельной системе заработок рабочего определяется как:", options: ["Произведение объема выполненных работ и расценки за единицу работ;", "Произведение объема выполненных работ и расценки за единицу работ с учетом премии за перевыполнение плана по выпуску продукции;", "Произведение количества отработанного времени (в днях) и дневной тарифной ставки рабочего;", "Произведение часовой тарифной ставки и установленной нормы времени (в часах);", "Отношение дневной тарифной ставки к сменной норме выработке;"], correct: 0, topic: "Оплата труда" },
    { id: 210, text: "Рабочих основного производства можно премировать за выполнение следующих показателей премирования:", options: ["Бездефектное изготовление продукции и сдача ее с первого требования.", "Сокращение сроков ремонта оборудования по сравнению с плановыми сроками при высоком качестве ремонтных работ;", "Сокращение простоев транспортных средств под погрузочно-разгрузочными операциями;", "Своевременный контроль качества изготавливаемой продукции;", "Отсутствие рекламаций;"], correct: 0, topic: "Оплата труда" },
    { id: 211, text: "Использование бестарифной формы оплаты труда предполагает учет следующих факторов:", options: ["Квалификационного уровня работника, количества отработанного времени и коэффициента трудового участия;", "Коэффициента трудового участия, отработанного времени работником и тарифного разряда работника;", "Квалификационного уровня работника, количества выпущенной продукции и тарифного разряда работника;", "Квалификационного уровня работника, количества выпущенной продукции и коэффициента трудового участия;", "Количества выпущенной продукции, расценки за единицу продукции и квалификационного уровня работника;"], correct: 0, topic: "Оплата труда" },
    { id: 212, text: "Дополнительный фонд заработной платы не включает один следующих элементов:", options: ["Оплату дней болезней;", "Оплату дней отпуска;", "Оплату дней работы в избирательной комиссии;", "Оплату дней ученического отпуска;", "Оплату дней заседания в сессии Городского совета;"], correct: 0, topic: "Оплата труда" },
    { id: 213, text: "Продолжительность рабочего дня равна 8 ч. при повременной заработной плате, равной 850 руб. Норма выработки составляет 25 изделий. Расценка за одно изделие при переводе работника с повременной на сдельную оплату труда составит ____ руб.", options: ["34;", "850;", "4,25;", "272"], correct: 0, topic: "Оплата труда" },
    { id: 214, text: "Заработная плата рабочего-повременщика 3-го разряда, имеющего тарифный коэффициент 1,2, составляет 3000 рублей в месяц, из которых 900 рублей составляет премиальная надбавка. Цена рабочего часа рабочего 1-го разряда, если в данном месяце было 25 рабочих дней по 8 рабочих часов, составляет ____ руб.", options: ["8,75;", "12,5;", "15,0;", "6,25"], correct: 0, topic: "Оплата труда" },
    { id: 215, text: "Основной фонд заработной платы не включает один следующих элементов:", options: ["Оплату дней выполнения государственных обязанностей;", "Отплату по тарифу;", "Доплату за работу в праздничные дни;", "Доплату за работу в ночное время;", "Доплату за совмещение профессий;"], correct: 0, topic: "Оплата труда" },
    { id: 216, text: "При простой повременной системе заработок рабочего определяется как:", options: ["Произведение количества отработанного времени (в днях) и дневной тарифной ставки рабочего;", "Произведение объема выполненных работ и расценки за единицу работ;", "Произведение количества отработанного времени (в часах) и часовой тарифной ставки рабочего с учетом премии за качественное изготовление продукции;", "Произведение часовой тарифной ставки и установленной нормы времени (в часах);", "Отношение дневной тарифной ставки к сменной норме выработке;"], correct: 0, topic: "Оплата труда" },
    { id: 217, text: "Рабочих ремонтных цехов можно премировать за выполнение следующих показателей премирования:", options: ["Увеличение межремонтного пробега оборудования.", "Сокращение простоев транспортных средств под погрузочно-разгрузочными операциями;", "Своевременный контроль качества изготавливаемой продукции;", "Отсутствие рекламаций;", "Бездефектное изготовление продукции и сдачи ее с первого требования;"], correct: 0, topic: "Оплата труда" },
    { id: 218, text: "Номинальная заработная плата – это:", options: ["Денежная сумма, которую получает работник за работу, выполненную в определенный период времени.", "Минимально необходимая сумма денежных средств, выплачиваемая работнику для поддержания трудоспособности;", "Количество товаров и услуг, выдаваемых работнику в качестве натуральной оплаты труда;", "Количество товаров и услуг, которые может позволить себе приобрести работник на свой денежный доход;", "Выбор максимально возможной суммы денежных средств, полученной работником, из ряда месяцев в течение года;"], correct: 0, topic: "Оплата труда" },
    { id: 219, text: "Системой повременной формы оплаты труда является:", options: ["Повременно-премиальная;", "Повременно-прогрессивная;", "Повременно-косвенная;", "Аккордная;", "Повременно-сдельная;"], correct: 0, topic: "Оплата труда" },
    { id: 220, text: "Реальная заработная плата – это:", options: ["Количество товаров и услуг, которые может позволить себе приобрести работник на свой денежный доход;", "Минимально необходимая сумма денежных средств, выплачиваемая работнику для поддержания трудоспособности;", "Количество товаров и услуг, выдаваемых работнику в качестве натуральной оплаты труда;", "Денежная сумма, которую получает работник за работу, выполненную в определенный период времени.", "Выбор максимально возможной суммы денежных средств, полученной работником, из ряда месяцев в течение года;"], correct: 0, topic: "Оплата труда" },
    { id: 221, text: "К элементам тарифной системы не относится:", options: ["Показатели премирования за повышение эффективности труда.", "Тарифная сетка;", "Тарифно-квалификационный справочник;", "Тарифные ставки;", "Надбавки и доплаты к тарифной ставке;", "Районные коэффициенты;"], correct: 0, topic: "Оплата труда" },
    { id: 222, text: "Принцип определение цены в рамках ассортиментной группы предполагает установление:", options: ["В рамках одной ассортиментной группы более низкого уровня цен по основному товару и более высокого уровня цен для сопутствующих товаров;", "Единого уровня цен для всех товаров одной ассортиментной группы;", "В рамках одной ассортиментной группы более высокого уровня цен по основному товару и более низкого уровня цен для сопутствующих товаров;", "Единого уровня цен для всех товаров одной ассортиментной группы, применяя систему скидок с цены в зависимости от величины спроса на товар;", "Единого уровня цен для одного и того же товара, реализуемого на разных рынках, с применением системы сезонных или временных скидок;"], correct: 0, topic: "Ценообразование" },
    { id: 223, text: "В соответствии с принципом ценообразования, обеспечивающим получение целевой прибыли цена на продукцию определяется как:", options: ["Сумма себестоимости единицы продукции и отношение планируемой величины прибыли к объему реализации продукции;", "На уровне себестоимости единицы продукции;", "Сумма себестоимости единицы продукции и торговой накидки;", "Сумма себестоимости единицы продукции и нормы прибыли;", "Сумма себестоимости единицы продукции и коэффициента эластичности спроса на продукцию;"], correct: 0, topic: "Ценообразование" },
    { id: 224, text: "Принцип определение цены на основе ценовой дискриминации предполагает установление:", options: ["Разных уровней цен для одного и того же товара, реализуемого на разных рынках;", "Единого уровня цен для одного и того же товара, реализуемого на разных рынках;", "Разных уровней цен для различных модификаций, товара, реализуемого на одном и том же рынке;", "Единого уровня цен для одного и того же товара, реализуемого на разных рынках, с применением системы сезонных или временных скидок;", "Диапазона цен для ряда товаров одной ассортиментной группы;"], correct: 0, topic: "Ценообразование" },
    { id: 225, text: "Годовой фонд заработной платы основных рабочих составляет 236,8 тыс. р., вспомогательных рабочих – 94,7 тыс.р., руководителей, специалистов и служащих – 426,5 тыс.р. Отчисления на социальные нужды – 30,4%. Расходы на содержание и эксплуатацию оборудования - 272 тыс. р. Стоимость оборудования – 14528,0 тыс.р. Общепроизводственные расходы, приходящиеся на данный продукт, – 612 тыс. р. Общехозяйственные расходы, приходящиеся на данный продукт, – 375 тыс. р. Коммерческие расходы – 1% от производственной себестоимости. Годовой выпуск продукции составляет 320 тыс. т. Таблица 4 – Расходы на производство 1 т продукции <Сырье и материалы: мел — норма расхода 0,218 т, цена 8,64 р.; суперфосфат простой — норма расхода 1,036 т, цена 83,9 р. Топливо и энергия на технологические цели: топливо — норма расхода 0,106 т, цена 10,33 р.; электроэнергия — норма расхода 41 кВт·ч, цена 0,01 р.; вода — норма расхода 8,5 м³, цена 0,01 р.>  Определите цеховую себестоимость единицы продукции (р).", options: ["94,11;", "88,8;", "95,28;", "96,23;", "105,85;"], correct: 0, topic: "Себестоимость" },
    { id: 226, text: "Годовой фонд заработной платы основных рабочих составляет 236,8 тыс. р., вспомогательных рабочих – 94,7 тыс.р., руководителей, специалистов и служащих – 426,5 тыс.р. Отчисления на социальные нужды – 30,4%. Расходы на содержание и эксплуатацию оборудования - 272 тыс. р. Стоимость оборудования – 14528,0 тыс.р. Общепроизводственные расходы, приходящиеся на данный продукт, – 612 тыс. р. Общехозяйственные расходы, приходящиеся на данный продукт, – 375 тыс. р. Коммерческие расходы – 1% от производственной себестоимости. Годовой выпуск продукции составляет 320 тыс. т. Таблица 4 – Расходы на производство 1 т продукции <Сырье и материалы: мел — норма расхода 0,218 т, цена 8,64 р.; суперфосфат простой — норма расхода 1,036 т, цена 83,9 р. Топливо и энергия на технологические цели: топливо — норма расхода 0,106 т, цена 10,33 р.; электроэнергия — норма расхода 41 кВт·ч, цена 0,01 р.; вода — норма расхода 8,5 м³, цена 0,01 р.> Опрделелите производственную себестоимость единицу продукции (р)", options: ["95,28;", "94,11;", "88,8;", "96,23;", "105,85;"], correct: 0, topic: "Себестоимость" },
    { id: 227, text: "Годовой фонд заработной платы основных рабочих составляет 236,8 тыс. р., вспомогательных рабочих – 94,7 тыс.р., руководителей, специалистов и служащих – 426,5 тыс.р. Отчисления на социальные нужды – 30,4%. Расходы на содержание и эксплуатацию оборудования - 272 тыс. р. Стоимость оборудования – 14528,0 тыс.р. Общепроизводственные расходы, приходящиеся на данный продукт, – 612 тыс. р. Общехозяйственные расходы, приходящиеся на данный продукт, – 375 тыс. р. Коммерческие расходы – 1% от производственной себестоимости. Годовой выпуск продукции составляет 320 тыс. т. Таблица 4 – Расходы на производство 1 т продукции <Сырье и материалы: мел — норма расхода 0,218 т, цена 8,64 р.; суперфосфат простой — норма расхода 1,036 т, цена 83,9 р. Топливо и энергия на технологические цели: топливо — норма расхода 0,106 т, цена 10,33 р.; электроэнергия — норма расхода 41 кВт·ч, цена 0,01 р.; вода — норма расхода 8,5 м³, цена 0,01 р.> Определите долю условно-переменных затрат в структуре себестоимости продукции (%).", options: ["93,9", "88,8", "96,23", "6,1", "94,11"], correct: 0, topic: "Себестоимость" },
    { id: 228, text: "Чтобы получить полную себестоимость продукции необходимо:", options: ["К производственной себестоимости прибавить коммерческие расходы;", "К производственной себестоимости прибавить общехозяйственные расходы;", "Из производственной себестоимости вычесть коммерческие расходы;", "К общепроизводственным расходам прибавить общехозяйственные расходы;", "К общепроизводственным расходам прибавить коммерческие расходы;"], correct: 0, topic: "Себестоимость" },
    { id: 229, text: "Годовой фонд заработной платы основных рабочих составляет 236,8 тыс. р., вспомогательных рабочих – 94,7 тыс.р., руководителей, специалистов и служащих – 426,5 тыс.р. Отчисления на социальные нужды – 30,4%. Расходы на содержание и эксплуатацию оборудования - 272 тыс. р. Стоимость оборудования – 14528,0 тыс.р. Общепроизводственные расходы, приходящиеся на данный продукт, – 612 тыс. р. Общехозяйственные расходы, приходящиеся на данный продукт, – 375 тыс. р. Коммерческие расходы – 1% от производственной себестоимости. Годовой выпуск продукции составляет 320 тыс. т. Таблица 4 – Расходы на производство 1 т продукции <Сырье и материалы: мел — норма расхода 0,218 т, цена 8,64 р.; суперфосфат простой — норма расхода 1,036 т, цена 83,9 р. Топливо и энергия на технологические цели: топливо — норма расхода 0,106 т, цена 10,33 р.; электроэнергия — норма расхода 41 кВт·ч, цена 0,01 р.; вода — норма расхода 8,5 м³, цена 0,01 р.> Определите полную себестоимость единицы продукции (р).", options: ["96,23;", "95,28;", "94,11;", "88,8;", "105,85;"], correct: 0, topic: "Себестоимость" },
    { id: 230, text: "Годовой фонд заработной платы основных рабочих составляет 236,8 тыс. р., вспомогательных рабочих – 94,7 тыс.р., руководителей, специалистов и служащих – 426,5 тыс.р. Отчисления на социальные нужды – 30,4%. Расходы на содержание и эксплуатацию оборудования - 272 тыс. р. Стоимость оборудования – 14528,0 тыс.р. Общепроизводственные расходы, приходящиеся на данный продукт, – 612 тыс. р. Общехозяйственные расходы, приходящиеся на данный продукт, – 375 тыс. р. Коммерческие расходы – 1% от производственной себестоимости. Годовой выпуск продукции составляет 320 тыс. т. Таблица 4 – Расходы на производство 1 т продукции <Сырье и материалы: мел — норма расхода 0,218 т, цена 8,64 р.; суперфосфат простой — норма расхода 1,036 т, цена 83,9 р. Топливо и энергия на технологические цели: топливо — норма расхода 0,106 т, цена 10,33 р.; электроэнергия — норма расхода 41 кВт·ч, цена 0,01 р.; вода — норма расхода 8,5 м³, цена 0,01 р.> Определите долю условно-постоянных затрат в структуре себестоимости продукции (%).", options: ["6,1", "93,9", "88,8", "96,23", "94,11"], correct: 0, topic: "Себестоимость" },
    { id: 231, text: "Что из нижеперечисленных расходов включается в себестоимость продукции в соответствии с классификацией по экономическим элементам:", options: ["Оплата командировочных расходов в пределах норматива;", "Материальная помощь работникам предприятия;", "Выплаты по акциям и вкладам трудового коллектива;", "Затраты на приобретение машин и оборудования, используемых в производственном процессе;", "Плата за выбросы вредных веществ сверх норматива загрязнения;"], correct: 0, topic: "Себестоимость" },
    { id: 232, text: "Себестоимость продукции представляет собой:", options: ["Затраты предприятия в стоимостном выражении, связанные с производством и реализацией продукции;", "Затраты предприятия в натуральном выражении, связанные с производством и реализацией продукции;", "Затраты предприятия на израсходованные материальные, трудовые ресурсы, необходимые для производства продукции, а также управленческие расходы;", "Явные и неявные издержки производства, связанные с изготовлением и реализацией продукции;", "Затраты предприятия в стоимостном выражении по переработке сырья и материалов с целью получения готовой продукции;"], correct: 0, topic: "Себестоимость" },
    { id: 233, text: "Чтобы рассчитать производственную себестоимость продукции необходимо:", options: ["К цеховой себестоимости прибавить общехозяйственные расходы;", "К цеховой себестоимости продукции прибавить затраты на переработку сырья и материалов для получения готовой продукции;", "К сумме общепроизводственных расходов прибавить общехозяйственные расходы;", "К цеховой себестоимости прибавить коммерческие расходы;", "Из суммы общехозяйственных расходов вычесть коммерческие расходы;"], correct: 0, topic: "Себестоимость" },
    { id: 234, text: "Что из нижеперчисленных расходов не входит в себестоимость продукции в соответствии с классификацией по экономическим элементам:", options: ["Затраты на отдых и лечение работников предприятия.", "Материальные ресурсы;", "Топливные и энергетические ресурсы;", "Затраты на оплату труда;", "Единый социальный налог;"], correct: 0, topic: "Себестоимость" },
    { id: 235, text: "В соответствии с классификацией себестоимости продукции по статьям калькуляции выделяют следующие статьи затрат:", options: ["Сырье и основные материалы, вспомогательные материалы, топливо и энергоресурсы, заработная плата основных рабочих, единый социальный налог, содержание и эксплуатация оборудования, общепроизводственные расходы, общехозяйственные расходы, коммерческие расходы;", "Сырье и основные материалы, вспомогательные материалы, топливо и энергоресурсы, заработная плата основных и вспомогательных рабочих, единый социальный налог, содержание и эксплуатация оборудования, общехозяйственные расходы, коммерческие расходы;", "Сырье и основные материалы, вспомогательные материалы, топливо и энергоресурсы, заработная плата рабочих, руководителей и служащих, единый социальный налог, содержание и эксплуатация оборудования, общехозяйственные расходы, коммерческие расходы;", "Сырье и основные материалы, вспомогательные материалы, топливо и энергоресурсы, заработная плата основных рабочих, единый социальный налог, содержание и эксплуатация оборудования, общехозяйственные расходы, коммерческие расходы;", "Сырье и основные материалы, вспомогательные материалы, топливо и энергоресурсы, заработная плата основных рабочих, содержание и эксплуатация оборудования, общепроизводственные расходы, коммерческие расходы;"], correct: 0, topic: "Себестоимость" },
    { id: 236, text: "В соответствии с классификацией себестоимости продукции по статьям калькуляции какая статья не включается в нее?", options: ["Заработная плата руководителей и специалистов основного производства;", "Сырье и основные материалы;", "Вспомогательные материалы;", "Топливо и энергоресурсы на технологические цели,", "Единый социальный налог;", "Содержание и эксплуатация оборудования,", "Общепроизводственные расходы;", "Общехозяйственные расходы;", "Коммерческие расходы;"], correct: 0, topic: "Себестоимость" },
    { id: 237, text: "К основным расходам не относится следующая статья затрат:", options: ["Общепроизводственные расходы;", "Сырье и основные материалы;", "Вспомогательные материалы;", "Топливо и энергоресурсы для технологических целей;", "Заработная плата основных производственных рабочих;"], correct: 0, topic: "Себестоимость" },
    { id: 238, text: "Прямые расходы не включают следующую статью затрат:", options: ["Общехозяйственные расходы;", "Содержание и эксплуатация оборудования;", "Заработная плата основных производственных рабочих;", "Вспомогательные материалы;", "Топливо и энергоресурсы на технологические цели;"], correct: 0, topic: "Себестоимость" },
    { id: 239, text: "К переменным затратам относится:", options: ["Заработная плата рабочих, находящихся на сдельной системе оплате труда;", "Амортизация оборудования;", "Затраты на ремонт оборудования;", "Заработная плата рабочих, находящихся на повременной системе оплате труда;", "Энергоресурсы, используемые для содержания зданий цеха;"], correct: 0, topic: "Себестоимость" },
    { id: 240, text: "Постоянные расходы включают в себя:", options: ["Заработную плату рабочих, находящихся на повременной системе оплате труда;", "Заработную плату рабочих, находящихся на сдельной системе оплате труда;", "Затраты на используемые сырье и основные материалы;", "Затраты на топливо и энергоресурсы для технологических целей;"], correct: 0, topic: "Себестоимость" },
    { id: 241, text: "Согласно методу калькуляции по способу суммирования затрат себестоимость продукции определяется как:", options: ["Отношение суммы калькуляционных статей, приходящихся на выпуск целевой продукции к объему целевой продукции.", "Сумма затрат по процессам технологического цикла и деления полученных сумм на фактическое количество выпущенной продукции;", "Отношение суммы всех затрат к сумме реализованной продукции и остатками продукции на складе;", "Сумма переменных затрат на единицу продукции и последующего добавления постоянных расходов в расчете на единицу продукции;", "Отношение суммы калькуляционных статей (рассчитанных произведение норм расхода, объема выпущенной продукции и цены ресурса) к количеству произведенной продукции;"], correct: 0, topic: "Себестоимость" },
    { id: 242, text: "Согласно нормативному методу калькуляции себестоимость продукции определяется как:", options: ["Отношение суммы калькуляционных статей (рассчитанных произведение норм расхода, объема выпущенной продукции и цены ресурса) к количеству произведенной продукции;", "Сумма затрат по процессам технологического цикла и деления полученных сумм на фактическое количество выпущенной продукции;", "Отношение суммы всех затрат к сумме реализованной продукции и остатками продукции на складе;", "Сумма переменных затрат на единицу продукции и последующего добавления постоянных расходов в расчете на единицу продукции;", "Отношение суммы калькуляционных статей, приходящихся на выпуск целевой продукции к объему целевой продукции;"], correct: 0, topic: "Себестоимость" },
    { id: 243, text: "Согласно методу директ-костинг калькуляции себестоимость продукции определяется как:", options: ["Сумма переменных затрат на единицу продукции и последующего добавления постоянных расходов в расчете на единицу продукции;", "Сумма затрат по процессам технологического цикла и деления полученных сумм на фактическое количество выпущенной продукции;", "Отношение суммы всех затрат к сумме реализованной продукции и остатками продукции на складе;", "Отношение суммы калькуляционных статей (рассчитанных произведение норм расхода, объема выпущенной продукции и цены ресурса) к количеству произведенной продукции;", "Отношение суммы калькуляционных статей, приходящихся на выпуск целевой продукции к объему целевой продукции;"], correct: 0, topic: "Себестоимость" },
    { id: 244, text: "В соответствии с принципом ценообразования «издержки плюс прибыль» цена на продукцию определяется как:", options: ["Сумма себестоимости единицы продукции и нормы прибыли;", "На уровне себестоимости единицы продукции;", "Сумма себестоимости единицы продукции и отношение планируемой величины прибыли к объему реализации продукции;", "Сумма себестоимости единицы продукции и торговой накидки;", "Сумма себестоимости единицы продукции и коэффициента эластичности спроса на продукцию;"], correct: 0, topic: "Ценообразование" },
    { id: 245, text: "Какой вид ремонта, как правило, не входит в систему ППР (планово- предупредительных работ) на химическом предприятии:", options: ["Средний ремонт", "Капитальный ремонт", "Профилактический ремонт", "Текущий ремонт", "Нет правильного ответа"], correct: 0, topic: "Ремонт" },
    { id: 246, text: "Кто возглавляет ремонтную службу на химическом предприятии?", options: ["Главный механик", "Главный инженер", "Заместитель генерального директора по экономике и финансам", "Главный бухгалтер", "Руководитель отдела логистики"], correct: 0, topic: "Ремонт" },
    { id: 247, text: "Трц – 1, (где Трц - нормативная длительность ремонтного цикла, Тмп - нормативная длительность межремонтного пробега), рассчитывают:", options: ["Количество текущих ремонтов в ремонтном цикле", "Количество капитальных ремонтов в ремонтном цикле", "Количество текущих и капитальных ремонтов в ремонтном цикле", "Количество ревизий средств труда за год", "Нет правильного ответа"], correct: 0, topic: "Ремонт" },
    { id: 248, text: "Внутрипроизводственное (внутрифирменное) планирование - это:", options: ["Совокупность стратегического, тактического и оперативного планирования", "Разработка планов распределения ресурсов предприятия в процессе реализации стратегических целей; отражает интересы среднего и нижнего звена управления", "Направление планирования хозяйственной деятельности предприятия с учетом изменений внешней и внутренней среды на период от 10 до 25 лет", "Разработка производственной программы", "Разработка бизнес-плана"], correct: 0, topic: "Планирование" },
    { id: 249, text: "К стоимостным показателям производственной программы предприятия относятся:", options: ["Валовая, товарная и реализованная продукция", "Себестоимость продукции и рентабельность", "Затраты на 1 руб. товарной продукции", "Стоимость основных фондов и величина нормируемых оборотных средств"], correct: 0, topic: "Планирование" },
    { id: 250, text: "Какой показатель определяет возможный годовой объем выпуска продукции на предприятии:", options: ["Производственная мощность", "Производственный план", "Производственная программа", "Производственные фонды", "Производительный труд"], correct: 0, topic: "Производственная мощность" },
    { id: 251, text: "Главная цель бизнес-плана – это:", options: ["Получение прибыли", "Расширение предпринимательской деятельности", "Выпуск запланируемого объема продукции", "Привлечение новых инвестиций", "Оценка рисков"], correct: 0, topic: "Планирование" },
    { id: 252, text: "В логистике в классификации по времени не выделяются следующие виды запасов материальных ценностей:", options: ["Текущий", "Максимальный", "Пороговый", "Гарантийный", "Неликвидные"], correct: 0, topic: "Логистика" },
    { id: 253, text: "Как рассчитывается явочная численность основных рабочих на промышленных предприятиях:", options: ["Отношением трудоемкости продукции к фонду времени рабочего", "Вычитанием трудоемкости продукции из фонда рабочего времени", "Отношением числа рабочих мест к норме обслуживания", "Отношением фонда времени рабочего к трудоемкости продукции", "Суммированием трудоемкости продукции и фонда времени рабочего"], correct: 0, topic: "Персонал" },
    { id: 254, text: "Что служит основным источником образования фонда оплаты труда на предприятии в рыночной экономике:", options: ["Доход от реализации продукции", "Доход на капитал", "Дотации государства", "Налог на прибыль", "Доход на акции"], correct: 0, topic: "Оплата труда" },
    { id: 255, text: "Каким показателем характеризуется уровень роста производительности труда на предприятии:", options: ["Снижением трудоемкости единицы продукции", "Ростом коэффициента автоматизации труда", "Применением передового опыта", "Сокращением общей численности работающих", "Внедрением нового оборудования"], correct: 0, topic: "Производительность труда" }
];
